type StudySessionOptions = {
    devSkill?: string;
    focusSubject?: SubjectKey;
    focusIds?: string[];
    forceReview?: boolean;
    sessionKind?: SessionKind;
    sessionKey?: string;
    benchmarkId?: string;
};

export const useStudySession = (options: StudySessionOptions = {}) => {
    const finishReservationRef = useRef<FinishTestReservation | null>(null);
    const finishAnswersRef = useRef(new Map<string, boolean>());
    const [finishResumeIndex, setFinishResumeIndex] = useState<number | undefined>();
    const [finishLoadedKey, setFinishLoadedKey] = useState<string>();
    const [finishResult, setFinishResult] = useState<FinishTestResult | null>(null);
    const [queue, setQueue] = useState<Problem[]>([]);
    const [loading, setLoading] = useState(true);
    const [generationError, setGenerationError] = useState(false);

    const [profileId, setProfileId] = useState<string | null>(null);
    const [profile, setProfile] = useState<UserProfile | null>(null);
    const profileRef = useRef<UserProfile | null>(null);
    const blockIndexRef = useRef(0);
    const sessionRequestIdRef = useRef(0);
    const resultQueueRef = useRef<Promise<void>>(Promise.resolve());

    const sessionHistoryRef = useRef<SessionHistoryItem[]>([]);
    const sessionKey = options.sessionKey
        ?? [
            options.sessionKind || "normal",
            options.devSkill || "",
            options.focusSubject || "",
            options.focusIds?.join(",") || "",
            options.forceReview ? "1" : "0"
        ].join("|");

    // profileRef と state を同時に更新するヘルパー
    const updateProfile = useCallback((p: UserProfile | null) => {
        profileRef.current = p;
        setProfile(p);
    }, []);

    // Profile fetching with error handling
    useEffect(() => {
        logInDev("[useStudySession] fetching profile...");
        getActiveProfile()
            .then(p => {
                logInDev("[useStudySession] profile:", p);
                if (p) {
                    setProfileId(p.id);
                    updateProfile(p);
                } else {
                    logInDev("[useStudySession] no profile found");
                    setLoading(false);
                }
            })
            .catch(err => {
                errorInDev("[useStudySession] error fetching profile:", err);
                setLoading(false);
            });
    }, [updateProfile]);

    // ============================================================
    // Developer Mode Block Generation
    // ============================================================
    const generateDevBlock = (blockSize: number, blockIndex: number): Problem[] => {
        const q: Problem[] = [];
        const skillId = options.devSkill!;

        for (let i = 0; i < blockSize; i++) {
            const problem = safeGenerateProblem(
                () => generateMathProblem(skillId, { profile: profileRef.current || undefined }),
                () => createFallbackProblem('math', `dev mode: ${skillId}`),
                `dev mode generation`
            );

            q.push({
                ...problem,
                id: `${blockIndex}-dev-${i}-${Date.now()}`,
                subject: 'math',
                isReview: false
            });
        }

        return q;
    };

    // ============================================================
    // Focus Mode Block Generation
    // ============================================================
    const generateFocusBlock = async (
        _pid: string,
        blockIndex: number,
        blockSize: number,
        recentAttempts: { subject: SubjectKey; itemId: string; result: string; skipped?: boolean }[]
    ): Promise<Problem[]> => {
        const q: Problem[] = [];
        const subject = options.focusSubject!;
        const focusIds = options.focusIds!;
        const sessionKind = options.sessionKind || "normal";
        const isReviewSession = options.forceReview === true || sessionKind === "review";
        const recovery = profileRef.current?.finishRecovery?.math;

        const buildCooldownIds = (pending: string[]) =>
            buildVocabCooldownIds(recentAttempts, sessionHistoryRef.current, pending);

        for (let i = 0; i < blockSize; i++) {
            const id = focusIds[Math.floor(Math.random() * focusIds.length)];

            const problem = safeGenerateProblem(
                () => subject === 'math'
                    ? (isReviewSession && recovery && recovery.level === profileRef.current?.mathMainLevel
                        ? generateMathFinishRecoveryProblem(recovery, id, i) : undefined)
                        ?? generateMathProblem(id, { profile: profileRef.current || undefined })
                    : generateVocabProblem(id, { cooldownIds: buildCooldownIds([]), kanjiMode: profileRef.current?.kanjiMode }),
                () => createFallbackProblem(subject, `focus mode: ${id}`),
                `focus mode: ${id}`
            );

            q.push({
                ...problem,
                id: `${blockIndex}-focus-${i}-${Date.now()}`,
                subject,
                isReview: isReviewSession
            });
        }

        sessionHistoryRef.current = [
            ...sessionHistoryRef.current,
            ...q.map(item => ({ id: item.categoryId, subject: item.subject, isReview: item.isReview }))
        ];

        return q;
    };

    // ============================================================
    // Check Mode Block Generation
    // ============================================================
    const generateCheckBlock = async (
        activeProfile: UserProfile,
        blockIndex: number,
        blockSize: number,
        recentAttempts: { subject: SubjectKey; itemId: string; result: string; isReview: boolean; skipped?: boolean }[]
    ): Promise<Problem[] | null> => {
        let checkSubject: SubjectKey;

        if (activeProfile.subjectMode === "math") {
            checkSubject = "math";
        } else if (activeProfile.subjectMode === "vocab") {
            checkSubject = "vocab";
        } else {
            checkSubject = getMixSubject(recentAttempts);
        }

        const recentPool = recentAttempts
            .filter(r => r.subject === checkSubject && r.result !== "skipped")
            .map(r => r.itemId);
        const uniquePool = Array.from(new Set(recentPool));

        if (uniquePool.length === 0) {
            return null; // Fallback to normal generation
        }

        const q: Problem[] = [];
        const buildCooldownIds = (pending: string[]) =>
            buildVocabCooldownIds(recentAttempts, sessionHistoryRef.current, pending);

        for (let i = 0; i < blockSize; i++) {
            const id = uniquePool[Math.floor(Math.random() * uniquePool.length)];

            const problem = safeGenerateProblem(
                () => checkSubject === "math"
                    ? generateMathProblem(id, { profile: activeProfile })
                    : generateVocabProblem(id, { cooldownIds: buildCooldownIds([]), kanjiMode: activeProfile.kanjiMode }),
                () => createFallbackProblem(checkSubject, `check mode: ${id}`),
                `check mode: ${id}`
            );

            q.push({
                ...problem,
                id: `${blockIndex}-check-${i}-${Date.now()}`,
                subject: checkSubject,
                isReview: false
            });
        }

        sessionHistoryRef.current = [
            ...sessionHistoryRef.current,
            ...q.map(item => ({ id: item.categoryId, subject: item.subject, isReview: item.isReview }))
        ];

        return q;
    };

    // ============================================================
    // Normal Block Generation
    // ============================================================
    const generateNormalBlock = async (
        pid: string,
        activeProfile: UserProfile,
        blockIndex: number,
        blockSize: number,
        recentAttempts: { subject: SubjectKey; itemId: string; result: string; isReview: boolean; skipped?: boolean }[]
    ): Promise<Problem[]> => {
        const blockCounts = new Map<string, number>();
        const recentIds = sessionHistoryRef.current.slice(-COOLDOWN_WINDOW).map(h => h.id);

        // Determine subject
        const vocabStopped = new Set(await getSkippedItemsToday(pid, 'vocab'));
        const vocabDue = (await getReviewItems(pid, 'vocab')).filter(item => {
            const level = getWordLevel(item.id);
            const state = activeProfile.vocabLevels?.find(candidate => candidate.level === level);
            return level !== null && !vocabStopped.has(item.id)
                && level <= activeProfile.vocabMaxUnlocked
                && (!activeProfile.vocabLevels || state?.unlocked === true && state.enabled === true);
        });
        const forceVocabReviewBlock = shouldForceVocabReviewBlock(
            activeProfile.subjectMode,
            vocabDue.length,
            recentAttempts,
        );

        let subject: SubjectKey;
        if (activeProfile.subjectMode === 'math') {
            subject = 'math';
        } else if (activeProfile.subjectMode === 'vocab') {
            subject = 'vocab';
        } else if (forceVocabReviewBlock) {
            subject = 'vocab';
        } else {
            subject = getMixSubject(recentAttempts);
        }

        // Fetch required data based on subject
        const skippedToday = await getSkippedItemsToday(pid, subject);

        const q: Problem[] = [];
        const pendingMeta: { isReview: boolean; countsTowardReviewCap?: boolean }[] = [];
        const pendingVocabIds: string[] = [];

        if (subject === 'math') {
            const mathDue = await getReviewItems(pid, 'math');
            const unitPractice = await readRuntimeMathUnitPractice(db, activeProfile, new Date().toISOString());
            const weakMathIds = await getWeakMathSkillIds(pid);
            const maintenanceMathIds = await getMaintenanceMathSkillIds(pid);
            const retiredMathIds = await getRetiredMathSkillIds(pid);
            const mathLevel = activeProfile.mathMainLevel ?? 1;
            const availableMathSkills = getAvailableSkills(activeProfile.mathMaxUnlocked ?? mathLevel);
            const weakMathPool = weakMathIds.filter(id => availableMathSkills.includes(id));

            const plusLimit = Math.max(1, Math.floor(BLOCK_SIZE * 0.3));
            let plusCount = 0;

            for (let i = 0; i < blockSize; i++) {
                const dynamicRecentIds = [
                    ...recentIds,
                    ...q.filter(item => item.subject === "math").map(item => item.categoryId),
                ].slice(-COOLDOWN_WINDOW);

                const generatorOptions = {
                    cooldownIds: buildMathCooldownIds(recentAttempts, q.length),
                    skippedTodayIds: skippedToday,
                    blockCounts,
                    recentIds: dynamicRecentIds
                };

                const currentWeakCount = q.filter(
                    item => item.subject === 'math' && weakMathPool.includes(item.categoryId)
                ).length;

                const result = generateSingleMathProblem({
                    profile: activeProfile,
                    mathDue,
                    unitPractice,
                    weakMathPool,
                    maintenanceMathIds,
                    retiredMathIds,
                    options: generatorOptions,
                    canAddReview: canAddSessionReview(
                        sessionHistoryRef.current,
                        pendingMeta,
                        activeProfile.dailyGoal,
                    ),
                    currentWeakCount,
                    plusCount,
                    plusLimit
                });

                plusCount = result.newPlusCount;

                const problem: Problem = {
                    ...result.problem,
                    id: `${blockIndex}-${i}-${Date.now()}`,
                    subject: 'math',
                    isReview: result.isReview,
                    isMaintenanceCheck: result.isMaintenanceCheck
                };

                q.push(problem);
                markPicked(problem.categoryId, blockCounts);
                pendingMeta.push({
                    isReview: result.isReview,
                    countsTowardReviewCap: result.countsTowardReviewCap,
                });
            }
        } else {
            // Vocab generation
            const vocabLevelWeights = buildVocabLevelWeights(activeProfile);
            const weakVocabPool = await getWeakVocabIds(pid);
            let plusCount = 0;

            const buildCooldownIds = (pending: string[]) =>
                buildVocabCooldownIds(recentAttempts, sessionHistoryRef.current, pending);

            for (let i = 0; i < blockSize; i++) {
                const dynamicRecentIds = [
                    ...recentIds,
                    ...q.filter(item => item.subject === "vocab").map(item => item.categoryId),
                ].slice(-COOLDOWN_WINDOW);

                const generatorOptions = {
                    cooldownIds: buildCooldownIds(pendingVocabIds),
                    skippedTodayIds: skippedToday,
                    blockCounts,
                    recentIds: dynamicRecentIds
                };

                const currentWeakCount = q.filter(
                    item => item.subject === 'vocab' && weakVocabPool.includes(item.categoryId)
                ).length;

                const result = generateSingleVocabProblem({
                    profile: activeProfile,
                    vocabDue,
                    vocabLevelWeights,
                    options: generatorOptions,
                    canAddReview: canAddSessionReview(
                        sessionHistoryRef.current.filter(item => item.subject === 'vocab'),
                        pendingMeta,
                        activeProfile.dailyGoal,
                    ),
                    forceReviewBlock: forceVocabReviewBlock,
                    blockSize,
                    currentReviewCount: pendingMeta.filter(item => item.countsTowardReviewCap).length,
                    weakVocabPool,
                    currentWeakCount,
                    plusCount,
                    pendingVocabIds,
                    buildCooldownIds
                });
                plusCount = result.newPlusCount;

                const problem: Problem = {
                    ...result.problem,
                    id: `${blockIndex}-${i}-${Date.now()}`,
                    subject: 'vocab',
                    isReview: result.isReview
                };

                q.push(problem);
                markPicked(problem.categoryId, blockCounts);
                pendingVocabIds.push(problem.categoryId);
                pendingMeta.push({
                    isReview: result.isReview,
                    countsTowardReviewCap: result.countsTowardReviewCap,
                });
            }
        }

        sessionHistoryRef.current = [
            ...sessionHistoryRef.current,
            ...q.map((item, index) => ({
                id: item.categoryId,
                subject: item.subject,
                isReview: item.isReview,
                countsTowardReviewCap: pendingMeta[index]?.countsTowardReviewCap ?? item.isReview,
            }))
        ];

        return q;
    };

    // ============================================================
    // Main Block Generation Entry Point
    // ============================================================
    const generateRawBlock = async (pid: string, activeProfile: UserProfile, blockIndex: number): Promise<Problem[]> => {
        const sessionKind = options.sessionKind || "normal";
        const blockSize = resolveSessionBlockSize(sessionKind);

        // Presentation throughput fixtures are intentionally DEV-only and run
        // inside the existing non-recording developer session. This is not a
        // planner result and must never be used as evidence of SRS selection.
        if (
            import.meta.env.DEV
            && sessionKind === "dev"
            && options.benchmarkId === COLD_OPEN_FIXED_TEN_ID
        ) {
            return createColdOpenFixedTenBlock(`${COLD_OPEN_FIXED_TEN_ID}:${blockIndex}`);
        }

        // Developer mode: generate only specified skill
        if (options.devSkill) {
            return generateDevBlock(blockSize, blockIndex);
        }

        // Special Check Mode (Event) -> Use Strict Level Logic (Same as Paper Test)
        if (sessionKind === "check-event") {
            return generateLevelBlock(activeProfile, blockSize);
        }

        if (sessionKind === "finish-test") {
            const subject = options.focusSubject || (activeProfile.subjectMode === "vocab" ? "vocab" : "math");
            const set = await reserveFinishTest(activeProfile.id, subject);
            finishReservationRef.current = set;
            const answers = Object.entries(set.answers ?? {});
            answers.forEach(([index, correct]) => finishAnswersRef.current.set(`finish-${set.id}-${index}`, correct));
            let resumeIndex = 0;
            while (set.answers?.[String(resumeIndex)] !== undefined && resumeIndex < 20) resumeIndex++;
            setFinishResumeIndex(resumeIndex);
            setFinishLoadedKey(sessionKey);
            return set.problems.map((p, i) => ({ ...p, id: `finish-${set.id}-${i}`, subject, isReview: false }));
        }

        // New Periodic Test (Plan A)
        if (sessionKind === "periodic-test") {
            const subject: SubjectKey =
                options.focusSubject ||
                (activeProfile.subjectMode === "vocab" ? "vocab" : "math");
            const set = await ensurePeriodicTestSet(activeProfile, subject);
            return set.problems.map((p, i) => ({
                ...p,
                id: `test-${i}-${Date.now()}`,
                subject,
                isReview: false
            }));
        }

        // New Weakness Review (Plan A)
        if (sessionKind === "weak-review") {
            // Need to fetch context data
            const [weakMathIds, weakVocabIds, skippedMathIds, skippedVocabIds] = await Promise.all([
                getWeakMathSkillIds(pid),
                getWeakVocabIds(pid),
                getSkippedItemsToday(pid, 'math'),
                getSkippedItemsToday(pid, 'vocab'),
            ]);

            return generateWeakReviewBlock(options.focusSubject
                ? { ...activeProfile, subjectMode: options.focusSubject }
                : activeProfile, {
                weakMathIds,
                weakVocabIds,
                skippedMathIds,
                skippedVocabIds,
                maintenanceMathIds: [],
                mathDue: [],
                vocabDue: [],
            });
        }

        const recentAttempts = await getRecentAttempts(pid, REVIEW_BLOCK_CHECK_WINDOW);

        // Focus mode: generate only specified IDs
        if (options.focusSubject && options.focusIds && options.focusIds.length > 0) {
            return generateFocusBlock(pid, blockIndex, blockSize, recentAttempts);
        }

        // Check mode (Normal): generate from recent history
        if (sessionKind === "check-normal") {
            const mappedAttempts = recentAttempts.map(a => ({
                ...a,
                isReview: a.isReview ?? false
            }));
            const checkResult = await generateCheckBlock(activeProfile, blockIndex, blockSize, mappedAttempts);
            if (checkResult) {
                return checkResult;
            }
            // Fallback to normal generation if no recent items
        }

        // Normal mode
        const mappedAttempts = recentAttempts.map(a => ({
            ...a,
            isReview: a.isReview ?? false
        }));
        return generateNormalBlock(pid, activeProfile, blockIndex, blockSize, mappedAttempts);
    };

    const generateBlock = async (pid: string, activeProfile: UserProfile, blockIndex: number): Promise<Problem[]> =>
        prepareStudyBlockPresentation(
            await generateRawBlock(pid, activeProfile, blockIndex),
            activeProfile.hissanModeEnabled ?? true,
            options.sessionKind === 'finish-test' || options.sessionKind === 'periodic-test' || options.benchmarkId === COLD_OPEN_FIXED_TEN_ID,
        );

    // ============================================================
    // Session Management
    // ============================================================
    const initSession = async () => {
        logInDev("[useStudySession] initSession called, profileId:", profileId, "sessionKey:", sessionKey);
        if (!profileId || !profileRef.current) return;

        const requestId = ++sessionRequestIdRef.current;
        setLoading(true);
        setGenerationError(false);
        setQueue([]);
        blockIndexRef.current = 1;
        sessionHistoryRef.current = [];
        finishReservationRef.current = null;
        finishAnswersRef.current.clear();
        setFinishResult(null);
        setFinishResumeIndex(undefined);
        setFinishLoadedKey(undefined);

        try {
            logInDev("[useStudySession] generating block...");
            const q = await generateBlock(profileId, profileRef.current, blockIndexRef.current);
            if (sessionRequestIdRef.current !== requestId) {
                return;
            }
            logInDev("[useStudySession] generated queue:", q);
            setQueue(q);
        } catch (err) {
            if (sessionRequestIdRef.current !== requestId) {
                return;
            }
            errorInDev("[useStudySession] error generating block:", err);
            setGenerationError(true);
            // A failed test-range review stays empty for an explicit retry;
            // a generic fallback would silently change its learning scope.
            const fallbackQueue: Problem[] = [];
            if (options.sessionKind !== "weak-review" && options.sessionKind !== 'finish-test' && options.sessionKind !== 'periodic-test') {
                for (let i = 0; i < BLOCK_SIZE; i++) {
                    fallbackQueue.push({
                        ...createFallbackProblem('math', 'session init failure'),
                        id: `${blockIndexRef.current}-fallback-${i}-${Date.now()}`,
                        subject: 'math',
                        isReview: false
                    });
                }
            }
            setQueue(fallbackQueue);
        }

        if (sessionRequestIdRef.current === requestId) {
            setLoading(false);
        }
    };

    const nextBlock = async () => {
        const sessionKind = options.sessionKind || "normal";
        if (
            !profileId
            || isFixedSessionKind(sessionKind)
            || options.benchmarkId === COLD_OPEN_FIXED_TEN_ID
        ) return;

        const sessionRequestId = sessionRequestIdRef.current;
        setLoading(true);
        setGenerationError(false);
        const nextBlockIndex = blockIndexRef.current + 1;
        blockIndexRef.current = nextBlockIndex;

        try {
            // DBから最新プロファイルを取得（レベルアップ等の反映）
            const latestProfile = await getActiveProfile();
            const activeProfile = latestProfile || profileRef.current;
            if (!activeProfile) { setLoading(false); return; }
            updateProfile(activeProfile);

            const q = await generateBlock(profileId, activeProfile, nextBlockIndex);
            if (sessionRequestIdRef.current !== sessionRequestId) {
                return;
            }
            setQueue(prev => [...prev, ...q]);
        } catch (err) {
            if (sessionRequestIdRef.current !== sessionRequestId) {
                return;
            }
            errorInDev("[useStudySession] error generating next block:", err);
            setGenerationError(true);
            // Generate emergency fallback queue
            const fallbackQueue: Problem[] = [];
            for (let i = 0; i < BLOCK_SIZE; i++) {
                fallbackQueue.push({
                    ...createFallbackProblem('math', 'next block failure'),
                    id: `${nextBlockIndex}-fallback-${i}-${Date.now()}`,
                    subject: 'math',
                    isReview: false
                });
            }
            setQueue(prev => [...prev, ...fallbackQueue]);
        }

        if (sessionRequestIdRef.current === sessionRequestId) {
            setLoading(false);
        }
    };

    // ============================================================
    // Result Handling
    // ============================================================
    const handleResult = (
        problem: Problem,
        result: 'correct' | 'incorrect' | 'skipped',
        timeMs?: number,
        learningEvidence?: LearningEvidenceContext,
    ): Promise<boolean> => {
        const processResult = async (): Promise<boolean> => {
            const sessionKind = options.sessionKind || "normal";
            if (sessionKind === 'finish-test' || sessionKind === 'periodic-test') {
                try {
                    if (!profileId || !await recordEvaluationContact(profileId, problem.subject, problem.categoryId)) return false;
                } catch (error) {
                    errorInDev('[useStudySession] error saving evaluation contact:', error);
                    return false;
                }
            }
            if (sessionKind === "finish-test") {
                const reservation = finishReservationRef.current;
                const index = queue.findIndex(item => item.id === problem.id);
                if (!reservation || index < 0 || problem.subject !== reservation.subject) return false;
                if (!finishAnswersRef.current.has(problem.id)) {
                    const correct = result === 'correct' && learningEvidence?.assistance === 'independent'
                        && learningEvidence.completion === 'whole-problem';
                    if (!await recordFinishTestAnswer(reservation, index, correct)) return false;
                    finishAnswersRef.current.set(problem.id, correct);
                }
                return true;
            }
            if (!shouldRecordLearningAttempt(sessionKind)) return true;
            if (!profileId) return false;

            const skipped = result === 'skipped';
            const scoredResult = result === 'correct' ? 'correct' : 'incorrect';
            let beforeAttempt: UserProfile | null;

            try {
                beforeAttempt = await getProfile(profileId);
                await logAttempt(
                    profileId,
                    problem.subject,
                    problem.categoryId,
                    scoredResult,
                    skipped,
                    problem.isReview,
                    problem.isMaintenanceCheck || false,
                    timeMs,
                    learningEvidence,
                );
            } catch (err) {
                errorInDev(
                    "[useStudySession] error saving attempt:",
                    err instanceof Error ? `${err.name}: ${err.message}` : err,
                );
                return false;
            }

            try {
                if (sessionKind === "weak-review" && skipped) {
                    const stoppedIds = await getSkippedItemsToday(profileId, problem.subject);
                    setQueue(previous => removeStoppedPendingQuestions(previous, problem, stoppedIds));
                }
                const currentProfile = await getActiveProfile();
                if (!currentProfile || currentProfile.id !== profileId) return true;
                // Hydrated memory is required for the next block's unattempted
                // vocab selection even when no level transition occurred.
                updateProfile(currentProfile);
                let triggerCheck: {
                    trigger: Awaited<ReturnType<typeof checkPeriodTestTrigger>>;
                    testSet?: ReturnType<typeof buildPeriodicTestSet>;
                } | null = null;
                if (sessionKind === "normal" || sessionKind === "review") {
                    try {
                        const triggerProfile = resolvePeriodicTestTriggerProfile(beforeAttempt, currentProfile, problem.subject);
                        const trigger = await checkPeriodTestTrigger(triggerProfile, problem.subject);
                        triggerCheck = {
                            trigger,
                            testSet: trigger.isTriggered
                                ? buildPeriodicTestSet(triggerProfile, problem.subject)
                                : undefined,
                        };
                    } catch (triggerError) {
                        errorInDev("[useStudySession] periodic test trigger check failed:", triggerError);
                    }
                }
                const updatedProfile = await resolveProfileProgressionAfterAttempt({
                    currentProfile,
                    subject: problem.subject,
                    nowIso: new Date().toISOString(),
                    checkMathUnlock: async (profileToCheck) => checkLevelProgression(profileToCheck.id, profileToCheck.mathMainLevel),
                    checkMathPromotion: checkMathMainPromotion,
                    checkVocabUnlockReadiness,
                    checkVocabPromotion: checkVocabMainPromotion,
                });

                if (updatedProfile !== currentProfile) {
                    const persistedProgression = await updateProfileAtomically(
                        profileId,
                        profileToUpdate => applyResolvedProgressionToLatestProfile({
                            baseProfile: currentProfile,
                            resolvedProfile: updatedProfile,
                            latestProfile: profileToUpdate,
                            subject: problem.subject,
                        }),
                    );
                    if (!persistedProgression) return true;
                    updateProfile({ ...persistedProgression, mathSkills: currentProfile.mathSkills, vocabWords: currentProfile.vocabWords });
                }

                if (triggerCheck) {
                    let didApplyPendingTest = false;
                    const profileWithPendingTest = await updateProfileAtomically(
                        profileId,
                        profileToUpdate => {
                            const nextProfile = applyPendingPeriodicTestTrigger(
                                profileToUpdate,
                                problem.subject,
                                triggerCheck.trigger,
                                triggerCheck.testSet,
                            );
                            if (!nextProfile) return profileToUpdate;
                            didApplyPendingTest = true;
                            return nextProfile;
                        },
                    );

                    if (profileWithPendingTest && didApplyPendingTest) {
                        logInDev(
                            `[Trigger] ${problem.subject} periodic test triggered!`,
                            triggerCheck.trigger.reason,
                        );
                        updateProfile({ ...profileWithPendingTest, mathSkills: currentProfile.mathSkills, vocabWords: currentProfile.vocabWords });
                    }
                }
            } catch (err) {
                // The atomic attempt write already succeeded. Unlock/promotion
                // checks are idempotent and will be evaluated again later.
                errorInDev("[useStudySession] post-attempt progression check failed:", err);
            }
            return true;
        };

        const releasePwaUpdateHold = holdPwaUpdateForCriticalPersistence();
        const queuedResult = resultQueueRef.current.then(processResult, processResult);
        resultQueueRef.current = queuedResult.then(() => undefined, () => undefined);
        return queuedResult.finally(releasePwaUpdateHold);
    };

    const initSessionOnProfileReady = useEffectEvent(() => {
        void initSession();
    });

    useEffect(() => {
        if (profileId) {
            initSessionOnProfileReady();
        }
    }, [profileId, sessionKey]);


    const blockSize = options.sessionKind === "weak-review" && queue.length > 0
        ? queue.length
        : resolveSessionBlockSize(options.sessionKind);

    const completeSession = async (
        sessionStats: {
            correct: number;
            total: number;
            durationSeconds: number;
            timeLimitSeconds?: number;
            timedOut?: boolean;
        }
    ): Promise<boolean> => {
        const releasePwaUpdateHold = holdPwaUpdateForCriticalPersistence();
        try {
            if (!profileId || !profile) return false;
            await resultQueueRef.current;
            const currentProfile = await getActiveProfile();
            if (!currentProfile || currentProfile.id !== profileId) return false;

            const sessionKind = options.sessionKind || "normal";
            if (sessionKind === "finish-test") {
                const reservation = finishReservationRef.current;
                if (!reservation) return false;
                const saved = await completeFinishTest(reservation, { ...sessionStats,
                    total: finishAnswersRef.current.size,
                    correct: [...finishAnswersRef.current.values()].filter(Boolean).length });
                if (!saved) return false;
                setFinishResult(saved.result);
                updateProfile(saved.profile);
                return true;
            }
            const persistedProfile = await updateProfileAtomically(
                profileId,
                async latestProfile => (
                    await resolveSessionCompletionProfileUpdate({
                        currentProfile: latestProfile,
                        sessionKind,
                        sessionStats,
                        now: Date.now(),
                        focusSubject: options.focusSubject,
                    }) ?? latestProfile
                ),
            );
            if (!persistedProfile) return false;
            updateProfile(persistedProfile);
            return true;
        } finally {
            releasePwaUpdateHold();
        }
    };

    return { finishResumeIndex: finishLoadedKey === sessionKey ? finishResumeIndex : undefined, finishResult, queue, initSession, nextBlock, handleResult, completeSession, loading, generationError, blockSize };
};

