                const carryingFood = resident.foodTrip?.phase === 'carry';
                if (foodCargos[index]) foodCargos[index].visible = carryingFood;
                const item = state.items.find(i => i.id === visit?.itemId && i.cell);
                const phase = activityPhase(state, resident, now);
                const caring = state.facilityPresentation === 'carry-care-v1' && resident.facilityTrip?.phase === 'carry' && resident.facilityTrip.kind === 'garden-hut';
                const scale = actor.scale.x;
                body.position.y = 0; body.rotation.set(0, 0, 0); actor.rotation.set(0, 0, 0);
                feet[index].forEach((foot, n) => { foot.position.copy(neutralFeet[index][n]); foot.rotation.set(0, 0, 0); });
                const rig = resident.id === 'rabbit' ? content.rabbit : resident.id === 'otter' ? content.otter : undefined;
                if (rig) { rig.head.rotation.set(0, 0, 0); rig.shoulders.forEach(shoulder => { shoulder.rotation.x = 0; }); poseResidentTail(rig.tail, resident.id === 'rabbit' ? 'rabbit' : 'otter', 0); }
                let position = point(resident.cell), seatGap: number | undefined, flowerLean = 0;
                if (visit && (item || isRoamVisit(visit))) {
                    const length = routeLength(visit.path);
                    const progress = length ? Math.max(0, Math.min(1, (now - visit.start) / (length * LIFE_STEP_MS))) : 0;
                    const step = (state.placementVersion === 1 ? progress : easeResident(progress)) * length;
                    let n = 0, covered = 0;
                    while (n < visit.path.length - 1) {
                        const distance = Math.hypot(visit.path[n + 1].x - visit.path[n].x, visit.path[n + 1].z - visit.path[n].z);
                        if (covered + distance > step) break;
                        covered += distance; n++;
                    }
                    const segment = n < visit.path.length - 1 ? Math.hypot(visit.path[n + 1].x - visit.path[n].x, visit.path[n + 1].z - visit.path[n].z) : 0;
                    const a = point(visit.path[n]), b = point(visit.path[Math.min(n + 1, visit.path.length - 1)]);
                    position = a.clone().lerp(b, segment ? (step - covered) / segment : 0);
                    if (a.distanceTo(b) > .01) {
                        const heading = Math.atan2(b.x - a.x, b.z - a.z);
                        const previous = point(visit.path[Math.max(0, n - 1)]);
                        const from = n > 0 ? Math.atan2(a.x - previous.x, a.z - previous.z) : 0;
                        actor.rotation.y = reduced ? heading : turnResidentToward(from, heading, (step - covered) * LIFE_STEP_MS);
                        if (!reduced) {
                            const stride = sampleResidentStride(step * RESIDENT_SCALE / scale, length * RESIDENT_SCALE / scale);
                            body.position.y = stride.bob;
                            feet[index].forEach((foot, f) => {
                                foot.position.y += stride.feet[f].lift;
                                foot.position.z += stride.feet[f].z - .12;
                            });
                            rig?.shoulders.forEach((shoulder, f) => { shoulder.rotation.x = stride.feet[f].arm; });
                        }
                    } else if (item) {
                        const target = point(item.cell!), walkedAt = visit.start + routeDuration(visit.path);
                        const duration = item.kind === 'flower' ? 400 : 900;
                        const settling = smoothArrival((now - walkedAt) / duration);
                        const previous = point(visit.path[Math.max(0, visit.path.length - 2)]);
                        const heading = previous.distanceTo(position) > .01
                            ? Math.atan2(position.x - previous.x, position.z - previous.z) : 0;
                        if (item.kind === 'flower' || item.kind === 'water-bowl') {
                            const facing = Math.atan2(target.x - position.x, target.z - position.z);
                            actor.rotation.y = reduced ? facing : turnToward(heading, facing, (now - walkedAt) / duration);
                            position.lerp(target, (item.kind === 'water-bowl' ? .38 : state.placementVersion === 1 ? 0 : caring ? .15 : .48) * settling);
                            body.rotation.x = ((caring ? .08 : .18) + (reduced ? 0 : Math.sin((now - walkedAt) / 950) * .045)) * settling;
                            flowerLean = caring ? 0 : settling;
                        } else if (isFacility(item.kind)) {
                            actor.rotation.y = reduced ? 0 : turnToward(heading, 0, (now - walkedAt) / 900);
                            (rig?.shoulders ?? heroArms).forEach(arm => { arm.rotation.x = -1 * settling; });
                        } else if (item.kind === 'sandbox') {
                            const facing = Math.atan2(target.x - position.x, target.z - position.z);
                            actor.rotation.y = reduced ? facing : turnToward(heading, facing, (now - walkedAt) / 900);
                            position.lerp(target, .30 * settling); body.rotation.x = .4 * settling;
                            const work = (-.9 + (reduced ? 0 : Math.sin((now - walkedAt) / 550) * .18)) * settling;
                            (rig?.shoulders ?? heroArms).forEach(arm => { arm.rotation.x = work; });
                        } else if (item.kind === 'sapling') {
                            const shaded = !caring && state.landscapeVersion === 'groves-water-v1' && growthStage(item) === 2;
                            const facing = shaded ? 0 : Math.atan2(target.x - position.x, target.z - position.z);
                            actor.rotation.y = reduced ? facing : turnToward(heading, facing, (now - walkedAt) / duration);
                            if (shaded) position.lerp(target, .44 * settling);
                        } else {
                            actor.rotation.y = reduced ? 0 : turnToward(heading, 0, (now - walkedAt) / duration);
                            const furniture = seats.get(item.id);
                            if (furniture) {
                                const usingMs = Math.max(0, now - walkedAt - duration);
                                const angle = item.kind === 'swing' && !reduced ? Math.sin((usingMs + decorationAt - now) / 1250) * .18 * Math.min(1, usingMs / 500) : 0;
                                if (furniture.pivot) furniture.pivot.rotation.x = angle;
                                body.position.y = -.08 * settling;
                                actor.rotation.x = angle;
                                if (rig) poseResidentTail(rig.tail, resident.id === 'rabbit' ? 'rabbit' : 'otter', settling);
                                feet[index].forEach((foot, f) => {
                                    foot.position.lerp(new T.Vector3(neutralFeet[index][f].x, -.06, .3), settling);
                                    foot.rotation.x = -.6 * settling;
                                });
                                content.world.updateMatrixWorld(true);
                                const role = item.kind === 'picnic-table' ? picnicRole(item, visit) : 0;
                                if (item.kind === 'picnic-table') actor.rotation.y = reduced ? picnic.facing(item, visit) : turnToward(heading, picnic.facing(item, visit), (now - walkedAt) / duration);
                                const top = (furniture.picnic?.seats[role] ?? furniture.seat).localToWorld(new T.Vector3(0, .05, 0));
                                const contactY = index === 0 ? .05 : residentSeatContactY(resident.id === 'rabbit' ? 'rabbit' : 'otter');
                                const offset = new T.Vector3(0, contactY * scale, 0).applyEuler(actor.rotation);
                                const seated = top.clone().sub(offset);
                                position.lerp(seated, settling);
                                actor.position.copy(position); actor.updateMatrixWorld(true);
                                if (settling === 1) seatGap = new T.Vector3(0, contactY, 0).applyMatrix4(actor.matrixWorld).distanceTo(top);
                            }
                        }
                    } else if (isRoamVisit(visit) && visit.path.length > 1) {
                        const previous = point(visit.path[visit.path.length - 2]);
                        actor.rotation.y = Math.atan2(position.x - previous.x, position.z - previous.z);
                    }
                }
                if (resident.facilityTrip?.phase === 'carry' || carryingFood) (rig?.shoulders ?? heroArms).forEach(arm => { arm.rotation.x = -1; });
                const reaction = resident.facilityTrip ? undefined : residentReaction(state, resident, now), hop = reduced ? 0 : reaction?.hop ?? 0;
                position.y += hop;
                actor.position.copy(position);
                if (rig) {
                    const elapsed = reaction?.symbol === '♪' ? favoriteReactionElapsed(state, resident, now) : undefined;
                    const interest = elapsed === undefined ? undefined
                        : sampleResidentInterest(resident.id === 'rabbit' ? 'rabbit' : 'otter', elapsed / 2400, reduced);
                    if (interest) {
                        rig.head.rotation.x = interest.headPitch;
                        rig.head.rotation.z = interest.headRoll;
                    } else if (!reduced && phase !== 'walking') {
                        rig.head.rotation.z = Math.sin(decorationAt / 1800 + index) * .035;
                    }
                    if (flowerLean > 0) {
                        // The muzzle lowers as the feet settle, then makes two
                        // small sniffs during the existing favorite reply.
                        const sniff = elapsed === undefined || reduced ? 0
                            : Math.sin(Math.min(1, elapsed / 1200) * Math.PI * 4)
                                * Math.sin(Math.min(1, elapsed / 1200) * Math.PI) * .045;
                        rig.head.rotation.x += (.09 + sniff) * flowerLean;
                    }
                }
                const scarf = content.hero.getObjectByName('life-scarf');
                if (index === 0 && scarf) scarf.position.y = .59 + body.position.y;
                return { id: resident.id, itemId: visit?.itemId, phase, foodCargo: carryingFood, position: actor.position.toArray(), seatGap, reaction: reaction?.symbol, hop,
                    headPitch: rig?.head.rotation.x ?? 0, headRoll: rig?.head.rotation.z ?? 0 };
            });
            content.world.updateMatrixWorld(true);
            const facilityUse = facilityMotion(visible, now, reduced);
            const sandWork = sandMotion(visible, now, reduced);
            audit.forEach((pose, index) => {
                pose.facilityUse = facilityUse.get(pose.id);
                pose.sandWork = sandWork.get(pose.id);
                pose.relation = pose.facilityUse ? undefined : gaze(visible, now, reduced, index);
                pose.picnic = picnic.finish(visible, now, index, reduced);
                if (pose.picnic?.relation) pose.relation = pose.picnic.relation;
                pose.waterLook = waterGaze(visible, now, reduced, index);
                pose.windLook = pose.facilityUse ? undefined : windGaze(now, reduced, index, pose.phase);
                pose.headYaw = heads[index].rotation.y;
                pose.headPitch = heads[index].rotation.x;
            });
        },
    };
}

import { HOUR, type Cell, type LifeAction, type LifeRecord, type LifeState } from './model';
import { effectiveGrowthHours, GROWTH_WINDOW_MS, growthHoursRemaining } from './economyRules';
import { cellKey, landCells } from './space';
import { shadeInfluence, waterInfluence } from './waterChannels';

export interface SoilCutover {
    rules: 'island-soil-v1'; at: number; actionCount: number;
    priorActions: LifeAction[]; validationHash: string;
}

const BASE = .20;
// A three-hour half-life makes a changed water route visible during a return visit.
const RELAXATION = Math.LN2 / 3;
const clamp = (value: number) => Math.max(0, Math.min(1, value));

async function digest(cutover: SoilCutover) {
    const { validationHash: ignored, ...payload } = cutover; void ignored;
    const bytes = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(JSON.stringify(payload)));
    return Array.from(new Uint8Array(bytes), byte => byte.toString(16).padStart(2, '0')).join('');
}

export async function prepareSoilCutover(record: LifeRecord): Promise<LifeRecord> {
    if (record.soilCutover) {
        if (record.soilCutover.validationHash !== await digest(record.soilCutover)) throw new Error('土の切替記録を確認できません。');
        return record;
    }
    if (!record.foodCutover) throw new Error('島の食べものをよみなおしてから始めてね。');
    const cutover: SoilCutover = { rules: 'island-soil-v1', at: record.now,
        actionCount: record.actions.length, priorActions: structuredClone(record.actions), validationHash: '' };
    cutover.validationHash = await digest(cutover);
    return { ...record, soilCutover: cutover };
}

export function beginSoilMoisture(state: LifeState) {
    if (state.soilMoisture) return;
    state.soilMoisture = Object.fromEntries(landCells(state).map(cell => [cellKey(cell), BASE]));
}

export function syncSoilCells(state: LifeState) {
    if (!state.soilMoisture) return;
    for (const cell of landCells(state)) state.soilMoisture[cellKey(cell)] ??= BASE;
}

export function soilMoistureAt(state: LifeState, cell: Cell) {
    return state.soilMoisture?.[cellKey(cell)] ?? BASE;
}

export function soilWetness(value: number) { return clamp((value - BASE) / .5); }

export function soilTarget(state: LifeState, cell: Cell, elapsedGrowthHours = 0) {
    return clamp(BASE + .50 * waterInfluence(state, cell) + .08 * shadeInfluence(state, cell, elapsedGrowthHours));
}

function relaxed(start: number, target: number, hours: number) {
    return target + (start - target) * Math.exp(-RELAXATION * hours);
}

function average(start: number, target: number, hours: number) {
    return hours ? target + (start - target) * -Math.expm1(-RELAXATION * hours) / (RELAXATION * hours) : start;
}

function averageWetness(start: number, target: number, hours: number) {
    if (hours <= 0) return soilWetness(start);
    const end = relaxed(start, target, hours), full = BASE + .5;
    if (start <= full && end <= full) return soilWetness(average(start, target, hours));
    if (start >= full && end >= full) return 1;
    const crossing = Math.max(0, Math.min(hours, -Math.log((full - target) / (start - target)) / RELAXATION));
    if (start < full) return (crossing * soilWetness(average(start, target, crossing)) + hours - crossing) / hours;
    return (crossing + (hours - crossing) * soilWetness(average(full, target, hours - crossing))) / hours;
}

export interface SoilStep { intervals: { growthFrom: number; growthHours: number; wallHours: number }[] }

/** One clock plan is shared by all cells and planters in a replay step. */
export function planSoilStep(state: LifeState, wallHours: number, growthHours: number): SoilStep {
    const transitions = growthHours > 0 ? state.items.filter(item => item.kind === 'sapling' && item.cell)
        .map(item => 18 - item.growth).filter(at => at > 0 && at < growthHours).sort((a, b) => a - b) : [];
    const expiries = growthHours > 0 && state.economy ? state.economy.completionTimes
        .map(at => at + GROWTH_WINDOW_MS).filter(at => at > state.now && at < state.now + wallHours * HOUR)
        .map(at => effectiveGrowthHours(state.economy!.completionTimes, state.now, at))
        .filter(at => at > 0 && at < growthHours) : [];
    const boundaries = growthHours > 0 ? [0, ...new Set([...transitions, ...expiries])].sort((a, b) => a - b).concat(growthHours) : [0, 1];
    let previousWall = 0;
    const intervals: SoilStep['intervals'] = [];
    for (let index = 1; index < boundaries.length; index++) {
        const from = boundaries[index - 1], to = boundaries[index];
        const endWall = index === boundaries.length - 1 ? wallHours : state.economy
            ? Math.min(wallHours, growthHoursRemaining(state.economy.completionTimes, state.now, to))
            : wallHours * to / growthHours;
        intervals.push({ growthFrom: growthHours > 0 ? from : 0, growthHours: growthHours > 0 ? to - from : 0, wallHours: endWall - previousWall });
        previousWall = endWall;
    }
    return { intervals };
}

/** Split at tree maturity and learning-window expiry for replay-size independence. */
export function soilCourse(state: LifeState, cell: Cell, wallHours: number, growthHours: number,
    step = planSoilStep(state, wallHours, growthHours)) {
    let moisture = soilMoistureAt(state, cell);
    const segments: { growthHours: number; shade: number; water: number }[] = [];
    for (const interval of step.intervals) {
        const shade = shadeInfluence(state, cell, interval.growthFrom);
        const target = soilTarget(state, cell, interval.growthFrom);
        segments.push({ growthHours: interval.growthHours, shade, water: averageWetness(moisture, target, interval.wallHours) });
        moisture = relaxed(moisture, target, interval.wallHours);
    }
    return { moisture: clamp(moisture), segments };
}

export function advanceSoilMoisture(state: LifeState, wallHours: number, growthHours: number,
    step = planSoilStep(state, wallHours, growthHours)) {
    if (!state.soilMoisture) return;
    syncSoilCells(state);
    for (const cell of landCells(state)) state.soilMoisture[cellKey(cell)] = soilCourse(state, cell, wallHours, growthHours, step).moisture;
}

import { growthStage, type Cell, type LifeItem, type LifeState } from './model';

/** Water and shade read only the placed items, so other island engines can share them. */
export interface WaterLayout {
    items: readonly Pick<LifeItem, 'kind' | 'cell' | 'growth'>[];
    /** Authored islands supply their water graph; walking edges grant no water connection. */
    neighbors?: (cell: Cell) => readonly Cell[];
}
import { cellKey, landCells } from './space';

const clamp = (value: number) => Math.max(0, Math.min(1, value));
const distance = (a: Cell, b: Cell) => Math.abs(a.x - b.x) + Math.abs(a.z - b.z);
const MAX_CHANNEL_STEPS = 8;
const directions = [{ x: 0, z: -1, bit: 1 }, { x: 1, z: 0, bit: 2 }, { x: 0, z: 1, bit: 4 }, { x: -1, z: 0, bit: 8 }];
const waterNeighbors = (state: WaterLayout, cell: Cell) => (state.neighbors?.(cell)
    ?? directions.map(({ x, z }) => ({ x: cell.x + x, z: cell.z + z })))
    .filter(next => Number.isInteger(cell.x) && Number.isInteger(cell.z) && Number.isInteger(next.x) && Number.isInteger(next.z) && distance(cell, next) === 1);

/** N/E/S/W bits describe the physical trench ends, including a neighboring bowl. */
export function waterChannelConnections(state: WaterLayout, cell: Cell) {
    const allowed = new Set(waterNeighbors(state, cell).map(cellKey));
    return directions.reduce((mask, { x, z, bit }) =>
        allowed.has(cellKey({ x: cell.x + x, z: cell.z + z })) && state.items.some(item => item.cell?.x === cell.x + x && item.cell?.z === cell.z + z
            && (item.kind === 'water-channel' || item.kind === 'water-bowl')) ? mask | bit : mask, 0);
}

/** Water bowls feed only adjacent channel pieces. A disconnected ditch remains dry. */
export function connectedWaterChannels(state: WaterLayout): Set<string> {
    const channels = new Map(state.items.filter(item => item.kind === 'water-channel' && item.cell)
        .map(item => [cellKey(item.cell!), item]));
    const bowls = state.items.filter(item => item.kind === 'water-bowl' && item.cell);
    const reached = new Set<string>();
    let frontier = [...channels.entries()].filter(([key, item]) => {
        if (!item.cell || !bowls.some(bowl => waterNeighbors(state, bowl.cell!).some(next => cellKey(next) === key))) return false;
        reached.add(key); return true;
    }).map(([key]) => key);
    for (let step = 1; step < MAX_CHANNEL_STEPS && frontier.length; step++) {
        const next: string[] = [];
        for (const key of frontier) {
            const item = channels.get(key)!;
            for (const nextCell of waterNeighbors(state, item.cell!)) {
                const neighbor = cellKey(nextCell);
                if (channels.has(neighbor) && !reached.has(neighbor)) { reached.add(neighbor); next.push(neighbor); }
            }
        }
        frontier = next;
    }
    return reached;
}

export function waterInfluence(state: WaterLayout, cell: Cell, reached = connectedWaterChannels(state)) {
    const sources = state.items.filter(item => item.cell && (item.kind === 'water-bowl'
        || item.kind === 'water-channel' && reached.has(cellKey(item.cell))));
    return Math.max(0, ...sources.map(item => clamp(1 - Math.max(0, distance(item.cell!, cell) - 1) / 3)));
}

export function shadeInfluence(state: WaterLayout, cell: Cell, elapsedGrowthHours = 0) {
    return Math.max(0, ...state.items.filter(item => item.kind === 'sapling' && item.cell
        && growthStage({ ...item, growth: item.growth + elapsedGrowthHours }) === 2)
        .map(item => clamp(1 - distance(item.cell!, cell) / 3)));
}

/** The current, deterministic moisture target for every owned land cell. */
export function landMoisture(state: LifeState): Record<string, number> {
    const reached = connectedWaterChannels(state);
    return Object.fromEntries(landCells(state).map(cell => [cellKey(cell), clamp(.20
        + .50 * waterInfluence(state, cell, reached) + .08 * shadeInfluence(state, cell))]));
}

import * as T from 'three';
import { batch, cylinder, ellipsoid, type IslandMaterials } from '../three/primitives';

/** Cheap, recognizable fallback and placement ghost; bounds fit the shared one-cell clearance. */
export function buildDecoration(kind: 'fence' | 'planter' | 'water-channel', materials: IslandMaterials, foodStage?: 0 | 1 | 2, waterFlow = false, waterConnections = 15) {
    const root = new T.Group(), paint = (color: string) => materials.surface(color, .8);
    if (kind === 'planter' && foodStage !== undefined) root.userData.foodStage = foodStage;
    if (kind === 'water-channel') {
        const strip = (width: number, depth: number, color: string, y: number, x = 0, z = 0) => {
            const mesh = new T.Mesh(new T.BoxGeometry(width, .025, depth), paint(color));
            mesh.position.set(x, y, z); mesh.receiveShadow = true; root.add(mesh); return mesh;
        };
        const color = waterFlow ? '#36b7d2' : '#b58b5d';
        strip(.28, .28, '#b99366', .014);
        strip(.20, .20, color, .09);
        for (const [bit, x, z, width, depth, wetWidth, wetDepth] of [
            [1, 0, -.25, .27, .5, .19, .5], [2, .25, 0, .5, .27, .5, .19],
            [4, 0, .25, .27, .5, .19, .5], [8, -.25, 0, .5, .27, .5, .19],
        ]) if (waterConnections & bit) {
            strip(width, depth, '#b99366', .014, x, z);
            strip(wetWidth, wetDepth, color, .09, x, z);
        }
        root.userData.waterFlow = waterFlow;
        root.userData.waterConnections = waterConnections;
    } else if (kind === 'fence') {
        const box = (x: number, y: number, w: number, h: number, d: number, color: string) => {
            const mesh = new T.Mesh(new T.BoxGeometry(w, h, d), paint(color)); mesh.position.set(x, y, 0);
            mesh.castShadow = mesh.receiveShadow = true; root.add(mesh);
        };
        for (const x of [-.34, .34]) { box(x, .26, .14, .52, .15, '#b8864e'); box(x, .53, .16, .05, .17, '#694325'); }
        for (const y of [.16, .38]) box(0, y, .8, .075, .09, '#b8864e');
    } else {
        const pot = new T.Mesh(new T.CylinderGeometry(.29, .23, .32, 16), paint('#b45e3f'));
        pot.position.y = .16; pot.castShadow = pot.receiveShadow = true; root.add(pot);
        for (const [x,z,h] of [[-.12,-.09,.52],[.12,-.08,.62],[0,.10,.56]]) {
            const height = foodStage === 0 ? .41 : foodStage === 1 ? h * .85 : h;
            cylinder(root,paint('#477b40'),[x,(height+.32)/2,z],.018,height-.32);
            ellipsoid(root,paint('#529047'),[x,.40,z],[foodStage === 0 ? .08 : .13,.08,.12],8);
            if (foodStage === undefined) {
                for(let i=0;i<5;i++){const a=i*Math.PI*2/5;ellipsoid(root,paint('#eaca6a'),[x+Math.cos(a)*.065,h,z+Math.sin(a)*.065],[.06,.025,.065],8);}
                ellipsoid(root,paint('#997135'),[x,h+.025,z],[.035,.018,.035],8);
            } else if (foodStage === 2) {
                for(let i=0;i<3;i++){const a=i*Math.PI*2/3;ellipsoid(root,paint('#db9a51'),[x+Math.cos(a)*.09,height,z+Math.sin(a)*.09],[.055,.055,.055],8);}
            }
        }
    }
    batch(root); return root;
}

import { runtimeAssetsEnabled, runtimeAssetSlot } from './runtimeAssetSlots';
import { occupiedCells } from '../../../domain/islandLife/footprint';
import { buildExtendedGround } from './extendedGround';
import { landBounds } from '../../../domain/islandLife/landRules';
import * as T from 'three';
import { batch, ellipsoid } from '../three/primitives';
import type { Cell, LifeState } from '../../../domain/islandLife/model';
import { createIslandGrassSurface } from '../three/grassSurface';
import { cellKey, districts, isHouse } from '../../../domain/islandLife/space';
import { plantGatherings } from '../../../domain/islandLife/discovery';
import { canopyShoreStudy, coastWorldOutline, makeCanopyShoreStudy } from './canopyShoreStudy';
import { canopyGroundVariant, makeCanopyGroundStudy } from './canopyGroundStudy';
