/** The playable rectangle stays level. Irregularity belongs outside its cells. */
export function coastShape(width: number, depth: number) {
    const x = width / 2, z = depth / 2;
    const curve = new T.CatmullRomCurve3([
        [-x + .5, -z], [-x * .35, -z - .12], [x * .35, -z + .03], [x - .4, -z],
        [x + .07, -z + .7], [x - .02, .1], [x + .12, z - .6], [x - .5, z + .04],
        [x * .25, z - .02], [-x * .35, z + .17], [-x + .45, z], [-x - .08, z - .6],
        [-x - .04, -.5], [-x + .01, -z + .55],
    ].map(([a, b]) => new T.Vector3(a, b, 0)), true);
    return new T.Shape(curve.getPoints(96).map(p => new T.Vector2(p.x, p.y)));
}

export function buildLandscape(state: LifeState, width: number, point: (c: Cell) => T.Vector3) {
    const root = new T.Group(); root.name = 'life-landscape';
    const materials = new Map<string, T.MeshStandardMaterial>();
    const paint = (color: string, roughness = .95) => {
        const key = `${color}:${roughness}`;
        if (!materials.has(key)) materials.set(key, new T.MeshStandardMaterial({ color, roughness }));
        return materials.get(key)!;
    };
    const land = (w: number, d: number, y: number, h: number, color: string) => {
        const geometry = new T.ExtrudeGeometry(coastShape(w, d), { depth: h, bevelEnabled: true, bevelThickness: .055, bevelSize: .075, bevelSegments: 3, steps: 1 });
        geometry.rotateX(-Math.PI / 2);
        const mesh = new T.Mesh(geometry, paint(color)); mesh.position.y = y;
        mesh.receiveShadow = true; root.add(mesh); return mesh;
    };
    const canopy = state.worldStyle === 'canopy-dots-c3-v1';
    const addedDepth = landBounds(state).depth - 5;
    const apron = canopy ? 1.35 : 0;
    const cliff = land(width + 1.7, 6.35 + addedDepth + apron, -.43, .23, '#9d8cb8');
    const sand = land(width + 1.95, 6.65 + addedDepth + apron, -.24, .15, '#ead7a8');
    const grass = land(width + 1.4, 5.65 + addedDepth + apron, -.16, .15, '#63cbb0');
    for (const layer of [cliff, sand, grass]) layer.position.z = (addedDepth - apron) / 2;
    const grassSurface = createIslandGrassSurface(grass.material, 'legacy-v1:moon-garden:ground');
    if (grassSurface) {
        grass.material = grassSurface.material;
        if (state.worldStyle === 'canopy-dots-c3-v1') grassSurface.material.bumpScale = .24;
    }
    const groundStudy = canopy && canopyGroundVariant ? makeCanopyGroundStudy(grass, root, (landBounds(state).minX + landBounds(state).maxX) / 2, canopyGroundVariant) : undefined;

    // Soft, still patches reveal the soil's actual stored moisture. The water
    // channel itself shows flow immediately; the neighboring earth lags behind.
    let soilSurface: T.ShaderMaterial | undefined;
    let soilGeometry: T.BufferGeometry | undefined;
    if (state.soilMoisture) {
        const positions: number[] = [], uvs: number[] = [], strengths: number[] = [], indices: number[] = [];
        for (const [key, moisture] of Object.entries(state.soilMoisture)) {
            const strength = soilWetness(moisture);
            if (strength < .04) continue;
            const [x, z] = key.split(',').map(Number);
            if (isHouse({ x, z })) continue;
            const p = point({ x, z }), index = positions.length / 3;
            for (const [dx, dz, u, v] of [[-.74, -.74, 0, 0], [.74, -.74, 1, 0], [.74, .74, 1, 1], [-.74, .74, 0, 1]]) {
                positions.push(p.x + dx, .082, p.z + dz); uvs.push(u, v); strengths.push(strength);
            }
            indices.push(index, index + 1, index + 2, index, index + 2, index + 3);
        }
        if (indices.length) {
            soilGeometry = new T.BufferGeometry();
            soilGeometry.setAttribute('position', new T.Float32BufferAttribute(positions, 3));
            soilGeometry.setAttribute('uv', new T.Float32BufferAttribute(uvs, 2));
            soilGeometry.setAttribute('strength', new T.Float32BufferAttribute(strengths, 1));
            soilGeometry.setIndex(indices);
            soilGeometry.computeBoundingSphere();
            soilSurface = new T.ShaderMaterial({ transparent: true, depthWrite: false, side: T.DoubleSide,
                uniforms: { color: { value: new T.Color('#327c91') } },
                vertexShader: 'attribute float strength; varying float vStrength; varying vec2 vUv; void main(){vStrength=strength;vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',
                fragmentShader: `uniform vec3 color; varying float vStrength; varying vec2 vUv;
                    void main(){float radius=length((vUv-.5)*2.0);float edge=1.0-smoothstep(.18,1.0,radius);
                    gl_FragColor=vec4(color,edge*vStrength*.34);
                    #include <tonemapping_fragment>
                    #include <colorspace_fragment>
                    }`,
            });
            const patches = new T.Mesh(soilGeometry, soilSurface); patches.name = 'life-soil-moisture';
            patches.renderOrder = 1; root.add(patches);
        }
    }

    // A broad, quiet water plane with a shallow shelf and low-contrast current.
    // It carries no hit targets and never changes simulation time or growth.
    const water = new T.ShaderMaterial({
        uniforms: { time: { value: 0 }, halfLand: { value: new T.Vector2((width + 1.9) / 2, 3.35 + (addedDepth + apron) / 2) },
            landOffset: { value: (apron - addedDepth) / 2 }, deep: { value: new T.Color('#355fc4') }, shallow: { value: new T.Color('#8bdbdd') } },
        vertexShader: 'varying vec2 vWorld; void main(){vec4 p=modelMatrix*vec4(position,1.0);vWorld=p.xz;gl_Position=projectionMatrix*viewMatrix*p;}',
        fragmentShader: `uniform float time; uniform float landOffset; uniform vec2 halfLand; uniform vec3 deep; uniform vec3 shallow; varying vec2 vWorld;
        float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
        float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);}
        void main(){
            vec2 q=abs(vWorld+vec2(0.0,landOffset))-halfLand+vec2(.7);
            float edge=length(max(q,0.0))+min(max(q.x,q.y),0.0)-.7;
            float shelf=1.0-smoothstep(.0,2.2,edge);
            vec3 color=mix(deep,shallow,shelf*.92);
            float ripple=sin(vWorld.y*6.0+noise(vWorld*.85)*5.0+time*.18);
            float threads=smoothstep(.93,1.0,ripple)*smoothstep(.3,.8,noise(vWorld*1.4))*(.035+shelf*.025);
            color+=vec3(threads);
            gl_FragColor=vec4(color,1.0);
            #include <tonemapping_fragment>
            #include <colorspace_fragment>
        }`,
    });
    const shoreStudy = canopy && canopyShoreStudy ? makeCanopyShoreStudy(water,
        coastWorldOutline(coastShape(width + 1.95, 6.65 + addedDepth + apron).getPoints()), (addedDepth - apron) / 2, canopyShoreStudy) : undefined;
    if (shoreStudy) root.userData.visualCandidate = `canopy-shore-${canopyShoreStudy}-study-v3`;
    const sea = new T.Mesh(new T.PlaneGeometry(120, 120), water); sea.rotation.x = -Math.PI / 2; sea.position.y = -.46; sea.name = 'life-sea'; root.add(sea);

    const edge = new T.Group(); edge.name = 'life-coast-plants'; root.add(edge);
    // Only low shoreline growth: the playable cell centers and approaches stay open.
    for (const side of [-1, 1]) for (let j = 0; j < 7 + Math.floor(addedDepth / .83); j++) {
        if ((j + side) % 3 === 0) continue;
        const x = side * (width / 2 + .48 + Math.sin(j * 2.1) * .08), z = -2.6 + j * .83;
        const stone = new T.Mesh(new T.IcosahedronGeometry(1, 0), paint(j % 2 ? '#a88bbc' : '#c9acd8'));
        stone.position.set(x + side * .22, -.18, z);
        stone.scale.set(.22 + (j % 3) * .065, .19, .24);
        stone.castShadow = stone.receiveShadow = true; edge.add(stone);
        stone.rotation.y = j * .7;
        if (runtimeAssetsEnabled) {
            const slot = new T.Group(); slot.position.copy(stone.position); slot.quaternion.copy(stone.quaternion); slot.scale.copy(stone.scale);
            stone.position.set(0, 0, 0); stone.rotation.set(0, 0, 0); stone.scale.setScalar(1);
            slot.add(stone); runtimeAssetSlot(slot, 'rock'); root.add(slot);
        }
        if (j % 3 !== 1) for (let k = 0; k < 4; k++) {
            const leaf = ellipsoid(edge, paint(k % 2 ? '#359c86' : '#72caa2'), [x + Math.sin(k * 2.3) * .12, .05 + k * .015, z + .17 + Math.cos(k * 2.3) * .10], [.075, .16, .035], 9);
            leaf.rotation.z = Math.sin(k * 2.3) * .65; leaf.rotation.x = Math.cos(k * 2.3) * .45;
        }
    }
    // Back edge gives the house a setting; the front edge remains low and clear.
    for (let j = 0; j < width + 1; j++) {
        if (j % 4 === 2 || j % 4 === 3) continue;
        const x = j - width / 2 + .2, z = -2.9 - Math.sin(j * 1.7) * .05;
        for (let k = 0; k < 3; k++) {
            const leaf = ellipsoid(edge, paint(k % 2 ? '#9162c0' : '#d176cf'), [x + k * .11, .10, z], [.16, .20 + k * .02, .09], 9);
            leaf.rotation.z = (k - 1) * .55;
        }
        if (j % 2 === 0) ellipsoid(edge, paint('#d5c7ab'), [x, -.14, 3.02 + addedDepth], [.15, .07, .10], 9);
    }
    batch(edge);

    const beds = new T.Group(); beds.name = 'life-district-ground'; root.add(beds);
    const plot = (x: number, z: number, w: number, d: number, color: string) => {
        const mesh = new T.Mesh(new T.BoxGeometry(w, .015, d), paint(color)); mesh.position.set(x, .057, z); mesh.receiveShadow = true; beds.add(mesh);
    };
    for (const district of districts(state)) {
        const cells = new Set(district.cells.map(cellKey));
        const hasSand = district.ids.some(id => state.items.some(i => i.id === id && i.kind === 'sandbox'));
        const soil = district.kind === 'flowers' ? '#b8a077' : '#cbd09a';
        for (const c of district.cells) {
            const p = point(c); plot(p.x, p.z, hasSand ? 1.12 : .94, hasSand ? 1.12 : .94, soil);
            // Join only cardinal neighbors. A hole in an L-shaped garden remains grass.
            for (const [dx, dz] of [[1, 0], [0, 1]]) if (cells.has(cellKey({ x: c.x + dx, z: c.z + dz }))) plot(p.x + dx * .5, p.z + dz * .5, dx ? .12 : .94, dz ? .12 : .94, soil);
            if (district.kind === 'flowers') for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
                if (cells.has(cellKey({ x: c.x + dx, z: c.z + dz }))) continue;
                for (let j = 0; j < 3; j++) {
                    const offset = (j - 1) * .30;
                    ellipsoid(beds, paint(j % 2 ? '#c6b89c' : '#e1ceaa'), [p.x + dx * .43 + dz * offset, .076, p.z + dz * .43 + dx * offset], [dx ? .05 : .14, .035, dz ? .05 : .14], 8);
                }
            }
        }
    }
    batch(beds);

    // Young plants already change the ground. Keep their low soil edge distinct
    // from a mature bed, and never draw two surfaces over the same mature cell.
    const extended = buildExtendedGround(state, point, paint); root.add(extended.root, extended.crowns);
    const young = new T.Group(); young.name = 'life-young-plant-ground'; root.add(young);
    const matureCells = new Set([...districts(state).filter(d => d.kind === 'flowers').flatMap(d => d.cells.map(cellKey)), ...extended.mature]);
    const soilPiece = (x: number, z: number, w: number, d: number, edge: boolean) => {
        const mesh = new T.Mesh(new T.BoxGeometry(w, edge ? .022 : .012, d), paint(edge ? '#b29a72' : '#c4ad85'));
        mesh.position.set(x, edge ? .063 : .055, z); mesh.receiveShadow = true; young.add(mesh);
    };
    for (const group of plantGatherings(state)) {
        const connected = new Set(group.map(item => cellKey(item.cell!)));
        for (const item of group) {
            const c = item.cell!; if (matureCells.has(cellKey(c))) continue;
            const p = point(c); soilPiece(p.x, p.z, .94, .94, false);
            for (const [dx, dz] of [[1, 0], [0, 1]]) {
                const neighbor = cellKey({ x: c.x + dx, z: c.z + dz });
                if (connected.has(neighbor) && !matureCells.has(neighbor)) soilPiece(p.x + dx * .5, p.z + dz * .5, dx ? .06 : .94, dz ? .06 : .94, false);
            }
            for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
                if (!connected.has(cellKey({ x: c.x + dx, z: c.z + dz }))) soilPiece(p.x + dx * .46, p.z + dz * .46, dx ? .035 : .94, dz ? .035 : .94, true);
            }
        }
    }
    batch(young);

    // Flat stepping stones borrow the old garden's path without reserving cells.
    // An owned item always wins over decoration, including after a move/reload.
    const occupied = new Set(state.items.flatMap(item => occupiedCells(item).map(cellKey)));
    const path = new T.Group(); path.name = 'life-doorstep-path'; root.add(path);
    for (let z = 1; z <= 4; z++) {
        const cell = { x: 2, z };
        if (occupied.has(cellKey(cell)) || isHouse(cell)) continue;
        const p = point(cell);
        for (let step = 0; step < 2; step++) {
            const stone = new T.Mesh(new T.CylinderGeometry(.21, .23, .018, 5), paint('#f3dda2'));
            stone.position.set(p.x + .26 + Math.sin(z * 3 + step) * .06, .052, p.z - .25 + step * .44);
            stone.rotation.y = z * .7 + step; stone.scale.z = .72; stone.receiveShadow = true;
            path.add(stone);
        }
    }
    return { root, animate: (at: number, reduced: boolean) => { water.uniforms.time.value = reduced ? 0 : at / 1000 % (Math.PI * 100); },
        dispose: () => { shoreStudy?.(); groundStudy?.(); materials.forEach(m => m.dispose()); grassSurface?.dispose(); soilGeometry?.dispose(); soilSurface?.dispose(); water.dispose(); } };
}

import { growthStage, type LifeAction, type LifeRecord, type LifeState, type ResidentId, type LifeItem, type Visit } from './model';
import { homeCell } from './space';

export type FriendId = Exclude<ResidentId, 'pokomoko'>;
export interface ResidencyCutover {
    rules: 'island-friends-v1'; profileId: string; at: number; actionCount: number;
    initialFriends: FriendId[]; priorActions: LifeAction[]; validationHash: string;
}
export interface ResidencyState {
    joined: FriendId[];
    invitations: Partial<Record<FriendId, { at: number; itemIds: string[]; reason: 'flowers' | 'water' | 'shared-meal' }>>;
}
async function digest(value: ResidencyCutover) {
    const { validationHash: ignored, ...payload } = value; void ignored;
    const bytes = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(JSON.stringify(payload)));
    return Array.from(new Uint8Array(bytes), byte => byte.toString(16).padStart(2, '0')).join('');
}
export async function prepareResidency(record: LifeRecord, newlyCreated: boolean): Promise<LifeRecord> {
    if (record.residencyCutover) {
        validateResidency(record);
        if (record.residencyCutover.validationHash !== await digest(record.residencyCutover)) throw new Error('なかまの記録を確認できません。');
        return { ...record, version: 21 };
    }
    const cutover: ResidencyCutover = { rules: 'island-friends-v1', profileId: record.profileId, at: record.now, actionCount: record.actions.length,
        initialFriends: newlyCreated ? [] : ['rabbit', 'otter'], priorActions: structuredClone(record.actions), validationHash: '' };
    cutover.validationHash = await digest(cutover);
    return { ...record, version: 21, residencyCutover: cutover };
}
export function validateResidency(record: LifeRecord) {
    const c = record.residencyCutover;
    if (record.version === 21 && !c || c && (record.version !== 21 || c.rules !== 'island-friends-v1' || c.profileId !== record.profileId || !record.soilCutover
        || !Number.isFinite(c.at) || !Array.isArray(c.initialFriends) || !Array.isArray(c.priorActions)
        || !/^[a-f0-9]{64}$/.test(c.validationHash)
        || c.at < record.soilCutover.at || c.at > record.now || !Number.isInteger(c.actionCount)
        || c.actionCount < record.soilCutover.actionCount || c.actionCount > record.actions.length
        || new Set(c.initialFriends).size !== c.initialFriends.length || c.initialFriends.some(id => !['rabbit', 'otter'].includes(id))
        || JSON.stringify(c.priorActions) !== JSON.stringify(record.actions.slice(0, c.actionCount))
        || record.actions.slice(0, c.actionCount).some(a => a.at > c.at)
        || record.actions.slice(c.actionCount).some(a => a.at < c.at))) throw new Error('なかまの切替記録を確認できません。');
    if (!c && record.actions.some(a => a.command.type === 'invite-friend')) throw new Error('なかまの切替記録がありません。');
}
export function beginResidency(state: LifeState, cutover: ResidencyCutover) {
    state.residency = { joined: [...cutover.initialFriends], invitations: {} };
    state.residents = state.residents.filter(r => r.id === 'pokomoko' || cutover.initialFriends.includes(r.id));
}
export function inviteFriend(state: LifeState, friend: FriendId) {
    if (!['rabbit', 'otter'].includes(friend) || !state.residency) throw new Error('なかまの記録をよみなおしてね。');
    if (state.residency.joined.includes(friend)) return;
    if (!state.residency.invitations[friend]) throw new Error('すきな ばしょが できたら あそびに くるよ。');
    state.residency.joined.push(friend);
    state.residents.push({ id: friend, cell: { ...homeCell }, enjoyed: 0, enjoyedBy: {} });
    state.residents.sort((a, b) => ['pokomoko', 'rabbit', 'otter'].indexOf(a.id) - ['pokomoko', 'rabbit', 'otter'].indexOf(b.id));
}
/** A completed, explicit hero visit supplies the invitation, never a purchase or timer alone. */
export function noticeFriendPlace(state: LifeState, residentId: ResidentId, item: LifeItem | undefined, visit: Visit, heroRequested: boolean) {
    const residence = state.residency;
    if (!residence || residentId !== 'pokomoko' || !item?.cell || (!heroRequested && !visit.observationTest)) return;
    const near = (other: LifeItem) => other.cell && Math.abs(other.cell.x - item.cell!.x) + Math.abs(other.cell.z - item.cell!.z) <= 2;
    const bloom = state.items.find(other => other.kind === 'flower' && growthStage(other) === 2 && near(other));
    const plant = state.items.find(other => ['flower', 'planter'].includes(other.kind) && near(other));
    const friend: FriendId | undefined = item.kind === 'bench' && bloom ? 'rabbit' : item.kind === 'water-bowl' && plant ? 'otter' : undefined;
    if (friend && !residence.joined.includes(friend) && !residence.invitations[friend]) {
        residence.invitations[friend] = { at: state.now, itemIds: [item.id, (friend === 'rabbit' ? bloom : plant)!.id], reason: friend === 'rabbit' ? 'flowers' : 'water' };
    }
}

/** Sustained real deliveries/meals can also welcome a friend; no currency or land gate. */
export function noticeSharedMeals(state: LifeState, tableId: string) {
    if (!state.residency || !state.food || state.food.delivered < 3 || state.food.eaten < 3) return;
    for (const friend of ['rabbit', 'otter'] as const) {
        if (!state.residency.joined.includes(friend) && !state.residency.invitations[friend]) {
            state.residency.invitations[friend] = { at: state.now, itemIds: [tableId], reason: 'shared-meal' };
        }
    }
}

export const ISLAND_SCREENS = ['home', 'help', 'learning', 'reward', 'inventory', 'placement', 'play', 'growth', 'album', 'customization', 'guide', 'experience', 'expression', 'showcase', 'workshop', 'camera', 'photos', 'shared', 'furniture', 'keepsakes', 'challenge'] as const;
export type IslandScreen = typeof ISLAND_SCREENS[number];
export type IslandHouseSection = 'home' | 'keepsakes' | 'notices';

export function islandHouseSectionFromSearch(search: string): IslandHouseSection {
    const query = new URLSearchParams(search);
    const section = query.get('house');
    return query.get('view') === 'keepsakes' && (section === 'keepsakes' || section === 'notices') ? section : 'home';
}

export function islandHouseUrl(section: IslandHouseSection) {
    return `/island?view=keepsakes${section === 'home' ? '' : `&house=${section}`}`;
}

export function islandScreenFromSearch(search: string): IslandScreen {
    const view = new URLSearchParams(search).get('view');
    return ISLAND_SCREENS.find(screen => screen === view && screen !== 'learning') ?? 'home';
}

export function islandLearningRequested(search: string) {
    const query = new URLSearchParams(search);
    return query.get('learn') === '1' || query.get('start') === 'learn';
}

/** Keep ordinary /learn in the same live learning host; a redirect would release
 * and immediately reacquire its Web Lock when returning from a checkpoint. */
export function islandLearningRoute(pathname: string, search: string) {
    const challenge = new URLSearchParams(search).get('challenge');
    return islandLearningRequested(search) || pathname === '/learn' && challenge !== 'math' && challenge !== 'vocab';
}

export function withoutIslandLearning(pathname: string, search: string) {
    const query = new URLSearchParams(search);
    query.delete('learn'); query.delete('start'); query.delete('profile');
    if (pathname === '/learn' && !['math', 'vocab'].includes(query.get('challenge') ?? '')) return '/island';
    return pathname + (query.size ? `?${query}` : '');
}

export function islandViewUrl(screen: IslandScreen) {
    return screen === 'home' ? '/island' : `/island?view=${screen}`;
}

export function islandFocusScreen(screen: IslandScreen, photo?: string | null) {
    return ['learning', 'placement', 'camera', 'showcase', 'workshop', 'reward', 'challenge'].includes(screen)
        || screen === 'photos' && Boolean(photo);
}

export function islandParentUrl(pathname: string, search: string) {
    if (islandLearningRequested(search)) return withoutIslandLearning(pathname, search);
    const query = new URLSearchParams(search);
    if (pathname === '/settings' && query.has('section')) return '/settings';
    if (pathname === '/settings/curriculum') return '/settings?section=learning';
    if (pathname === '/parents' || pathname === '/dev') return '/settings';
    if (pathname === '/island') {
        if (islandHouseSectionFromSearch(search) !== 'home') return islandHouseUrl('home');
        if (query.get('view') === 'challenge') return islandViewUrl('keepsakes');
        if (query.has('photo')) return islandViewUrl('photos');
        if (query.get('view') === 'placement') return islandViewUrl('inventory');
        if (query.get('view') === 'camera') return islandViewUrl('photos');
    }
    return '/island';
}

import { db, type SansuDatabase } from '../../db';
import { canonicalIslandPhotoAction, hasMatchingIslandPhotoBlobs, hasValidIslandPhotoMetadata, hasValidIslandPhotoReceipt,
    ISLAND_PHOTO_ALBUM_BYTES, ISLAND_PHOTO_LIMIT, IslandPhotoConflict, islandPhotoIntentDigest, islandPhotoReceiptId,
    normalizeIslandPhotoAlbum, normalizeIslandPhotoInput, validateIslandPhotoBlobs, validateIslandPhotoThumbnail,
    type IslandPhotoAction, type IslandPhotoAlbumSnapshot, type IslandPhotoBlobPair, type IslandPhotoInput, type IslandPhotoWriteResult } from './photos';

const invalid = () => new IslandPhotoConflict('invalid', 'しゃしんの きろくを たしかめてね');
const conflict = () => new IslandPhotoConflict('conflict', 'アルバムが かわったよ。もういちど ひらいてね');
/** Photos have their own small transaction boundary; never add these stores to learning/island writers. */
export const islandPhotoTables = (database: SansuDatabase) => [database.appData, database.islandPhotoAlbums,
    database.islandPhotos, database.islandPhotoBlobs, database.islandEvents];
async function assertOwner(database: SansuDatabase, profileId: string) {
    const app = await database.appData.get('app');
    if (!app || app.activeProfileId !== profileId || !Object.prototype.hasOwnProperty.call(app.profiles ?? {}, profileId) || app.profiles[profileId]?.id !== profileId) {
        throw new IslandPhotoConflict('inactive', 'この しゃしんの なかまに もどってね');
    }
}
const photoBytes = (snapshot: IslandPhotoAlbumSnapshot) => snapshot.photos.reduce((sum, photo) => sum + photo.image.bytes + photo.thumbnail.bytes, 0);
async function readSnapshot(database: SansuDatabase, profileId: string): Promise<IslandPhotoAlbumSnapshot> {
    const stored = await database.islandPhotoAlbums.get(profileId);
    const album = normalizeIslandPhotoAlbum(stored, profileId);
    const photos = await database.islandPhotos.where('profileId').equals(profileId).toArray();
    if (photos.some(photo => !hasValidIslandPhotoMetadata(photo, profileId)) || (!stored && photos.length)
        || photos.length > ISLAND_PHOTO_LIMIT) throw invalid();
    const snapshot = { album, photos: photos.sort((a, b) => b.capturedAt - a.capturedAt || a.id.localeCompare(b.id)) };
    if (photoBytes(snapshot) > ISLAND_PHOTO_ALBUM_BYTES) throw invalid();
    return snapshot;
}
async function assertPairs(database: SansuDatabase, profileId: string, snapshot: IslandPhotoAlbumSnapshot) {
    const blobs = await database.islandPhotoBlobs.where('profileId').equals(profileId).toArray();
    if (blobs.length !== snapshot.photos.length) throw invalid();
    const byId = new Map(blobs.map(blob => [blob.id, blob]));
    if (snapshot.photos.some(photo => !hasMatchingIslandPhotoBlobs(photo, byId.get(photo.id)))) throw invalid();
}
export async function readIslandPhotoAlbum(profileId: string, database = db): Promise<IslandPhotoAlbumSnapshot> {
    return database.transaction('r', [database.appData, database.islandPhotoAlbums, database.islandPhotos], async () => {
        await assertOwner(database, profileId);
        return readSnapshot(database, profileId);
    });
}
async function loadPhotoPair(profileId: string, photoId: string, database: SansuDatabase) {
    canonicalIslandPhotoAction({ type: 'delete-photo', photoId }, profileId);
    return database.transaction('r', [database.appData, database.islandPhotoAlbums, database.islandPhotos, database.islandPhotoBlobs], async () => {
        await assertOwner(database, profileId);
        const snapshot = await readSnapshot(database, profileId);
        const photo = snapshot.photos.find(entry => entry.id === photoId), blob = await database.islandPhotoBlobs.get(photoId);
        if (!photo && !blob) return undefined;
        if (!photo || !hasMatchingIslandPhotoBlobs(photo, blob)) throw invalid();
        return { photo, blobs: { image: blob.image, thumbnail: blob.thumbnail } };
    });
}
export async function loadIslandPhotoThumbnail(profileId: string, photoId: string, database = db): Promise<Blob | undefined> {
    const loaded = await loadPhotoPair(profileId, photoId, database);
    if (!loaded) return undefined;
    await validateIslandPhotoThumbnail(loaded.photo, loaded.blobs.thumbnail);
    return loaded.blobs.thumbnail;
}
export async function loadIslandPhotoBlobs(profileId: string, photoId: string, database = db): Promise<IslandPhotoBlobPair | undefined> {
    const loaded = await loadPhotoPair(profileId, photoId, database);
    if (!loaded) return undefined;
    // Digest and PNG inspection must stay outside the IndexedDB transaction.
    await validateIslandPhotoBlobs(loaded.photo, loaded.blobs);
    return loaded.blobs;
}
function quotaFailure(cause: unknown): boolean {
    const seen = new Set<unknown>();
    while (cause && typeof cause === 'object' && !seen.has(cause)) {
        seen.add(cause);
        if ('name' in cause && cause.name === 'QuotaExceededError') return true;
        cause = 'inner' in cause ? cause.inner : 'cause' in cause ? cause.cause : undefined;
    }
    return false;
}
async function write(profileId: string, expectedAlbumRevision: number, action: IslandPhotoAction,
    blobs: IslandPhotoBlobPair | undefined, database: SansuDatabase): Promise<IslandPhotoWriteResult> {
    const id = islandPhotoReceiptId(profileId, expectedAlbumRevision), intent = canonicalIslandPhotoAction(action, profileId);
    const intentDigest = await islandPhotoIntentDigest(intent);
    const photoId = intent.type === 'save-photo' ? intent.photo.id : intent.photoId;
    try {
        return await database.transaction('rw', islandPhotoTables(database), async () => {
            // Ownership precedes receipts: a deleted or inactive profile cannot replay a historical success.
            await assertOwner(database, profileId);
            const snapshot = await readSnapshot(database, profileId);
            await assertPairs(database, profileId, snapshot);
            const prior = await database.islandEvents.get(id);
            if (prior) {
                if (prior.type !== 'photo_changed' || prior.profileId !== profileId || !hasValidIslandPhotoReceipt(prior.photoReceipt, profileId)
                    || prior.photoReceipt.albumRevision !== expectedAlbumRevision || prior.photoReceipt.intentDigest !== intentDigest
                    || prior.photoReceipt.photoId !== photoId || prior.photoReceipt.result !== (intent.type === 'save-photo' ? 'saved' : 'deleted')
                    || JSON.stringify(canonicalIslandPhotoAction(prior.action, profileId)) !== JSON.stringify(intent)
                    || snapshot.album.revision <= expectedAlbumRevision) throw conflict();
                return { ...snapshot, photoId, present: snapshot.photos.some(photo => photo.id === photoId), replayed: true };
            }
            if (snapshot.album.revision !== expectedAlbumRevision) throw conflict();
            if (snapshot.album.revision === Number.MAX_SAFE_INTEGER) throw invalid();
            if (intent.type === 'save-photo') {
                if (!blobs || !hasMatchingIslandPhotoBlobs(intent.photo, { id: photoId, profileId, ...blobs })) throw invalid();
                // Global IDs must not overwrite an orphan or a foreign-owner row.
                if (await database.islandPhotos.get(photoId) || await database.islandPhotoBlobs.get(photoId)) throw conflict();
                if (snapshot.photos.length >= ISLAND_PHOTO_LIMIT || photoBytes(snapshot) + intent.photo.image.bytes + intent.photo.thumbnail.bytes > ISLAND_PHOTO_ALBUM_BYTES) {
                    throw new IslandPhotoConflict('full', 'アルバムが いっぱいだよ');
                }
                await database.islandPhotos.add(intent.photo);
                await database.islandPhotoBlobs.add({ id: photoId, profileId, image: blobs.image, thumbnail: blobs.thumbnail });
            } else {
                if (!snapshot.photos.some(photo => photo.id === photoId)) throw conflict();
                await database.islandPhotos.delete(photoId);
                await database.islandPhotoBlobs.delete(photoId);
            }
            await database.islandPhotoAlbums.put({ ...snapshot.album, revision: snapshot.album.revision + 1 });
            await database.islandEvents.add({ id, profileId, type: 'photo_changed', timestamp: Date.now(), action: intent,
                photoReceipt: { albumRevision: expectedAlbumRevision, intentDigest, photoId, result: intent.type === 'save-photo' ? 'saved' : 'deleted' } });
            return { ...await readSnapshot(database, profileId), photoId, present: intent.type === 'save-photo', replayed: false };
        });
    } catch (cause) {
        if (quotaFailure(cause)) throw new IslandPhotoConflict('quota', 'ほぞんする ばしょが いっぱいみたい');
        throw cause;
    }
}
export async function saveIslandPhoto(profileId: string, expectedAlbumRevision: number, input: IslandPhotoInput,
    blobs: IslandPhotoBlobPair, database = db): Promise<IslandPhotoWriteResult> {
    const photo = normalizeIslandPhotoInput(input, profileId);
    // Freeze references synchronously. The exact immutable pair and metadata bind every retry.
    const pair = { image: blobs?.image, thumbnail: blobs?.thumbnail };
    await validateIslandPhotoBlobs(photo, pair);
    return write(profileId, expectedAlbumRevision, { type: 'save-photo', photo }, pair, database);
}
export async function deleteIslandPhoto(profileId: string, expectedAlbumRevision: number, photoId: string, database = db): Promise<IslandPhotoWriteResult> {
    return write(profileId, expectedAlbumRevision, { type: 'delete-photo', photoId }, undefined, database);
}

# いつでも選び直せる身支度と、見つけた物の小さなコレクション

Date: 2026-09-08

Status: **採用・実装と検証は進行中。** この仕様の採用は、価格の妥当性、実装完了、実画面の魅力、子どもの再遊びの合格を意味しない。

親は[01](01_app_spec.md)。既存の無料設定と全景保存は[36](36_island_experience_spec.md)・[39](39_island_appearance_sets_spec.md)、観察と制作は[37](37_island_workshop_spec.md)、写真は[38](38_island_shared_memories_spec.md)、家具の暮らしは[40](40_island_life_furniture_spec.md)を前提にする。[追加報酬分析](../wiki/reward-customization-benchmark.md)のR09衣装・R10模様・R12足跡・R13音・R14アルバム装飾・R15旗と、[残差監査](../tasks/archive/2026-09-08-island-experience-remaining-audit.md)末尾のF05候補を具体化する。元資料の分析事実と、以下のSansuの採用設計を区別する。

## 1. 目的と範囲

好きな姿を実物で試す → 自分で取得する → 好きな仲間や景色に使う → 観察した出来事を思い出す → 保存した景色からまた選び直す、を任意の遊びとしてつなぐ。

衣装は住民本人の身支度、模様はその子を見分ける小さな印、足跡は実際に歩いた所へ残る短い表情、音は実演を見た記憶、表紙や旗は自分の島を見せる外装とする。取得数や残高を増やすことだけで用途を代替しない。

通常の入力、連問、予約、ヒント、お手本、復習、習得判定、基本成長は維持する。試用・取得・装備・写真・全景保存を学習開始や次の問題の必須操作にしない。音off、中断、支援、誤答によって取得資格や外見を劣らせず、成果を没収しない。

## 2. 最初の10取得品と無料の選択

商品IDは以下の有限集合とし、追加する時はカタログ、保存版、表示と受入を一緒に見直す。既存の12部位の外見カタログへ異なる権利を混ぜず、専用の `ISLAND_EXPRESSION_CATALOG` を設ける。通貨は既存のほしだけを使う。

| stable itemId | 表示名 | 対象 | ほし | 取得資格と取得後の用途 |
|---|---|---|---:|---|
| raincoat | あまがっぱ | 衣装 | 25 | 常設。住民の肩と胴を覆う布、開いた顔まわりで雨支度を表す |
| star-beret | ほしの ベレー | 衣装 | 20 | 常設。星の縫い飾りと柔らかい帽子の輪郭を、本人の頭に付ける |
| river-check | みずべチェック | 模様 | 10 | 常設。水色と濃淡のチェックを、本人の身支度の小さな布片へ付ける |
| butterfly-stitch | ちょうの ぬいめ | 模様 | 0 | 保存済み `ribbon-butterfly` 観察。蝶を見た記憶を縫い模様として使う |
| leaf-trail | はっぱの あしあと | 足跡 | 10 | 常設。歩いた接地点に少数の葉形を短く残す |
| water-ring-trail | みずの わ | 足跡 | 15 | 常設。歩いた接地点に小さな水輪を短く出す |
| shell-three-notes | かいの みっつの おと | 収集音 | 0 | 保存済みbellの `observe-creation`。工作で見届けた三音の短い音景を選ぶ |
| leaf-album-cover | はっぱの ひょうし | アルバム表紙 | 5 | 常設。写真棚の表紙と外周を葉の装丁にする |
| butterfly-stamp | ちょうの スタンプ | アルバム印 | 0 | 保存済み `ribbon-butterfly` 観察。写真の外側の余白へ小さな印を付ける |
| leaf-bird-flag-trim | ことりの はたかざり | 旗飾り | 0 | 保存済み `leaf-bird` 観察。既存の旗の縁へ葉鳥の飾りを添える |

6有料品の合計は85ほし、4品は観察資格による0ほしの明示取得。価格は既存の小品・部位・家具と選択を作る**初期仮説で未検証**。獲得倍率、所要日数、意欲への効果をここから断定しない。各商品はprofileごとに一度だけ所有し、衣装・模様・足跡は一度の取得で登場済みの全3住民へ繰り返し使える。住民別の再購入、消耗、維持費、抽選、追加課金はない。

朝 `morning`・昼 `day`・夕 `evening` と、春 `spring`・夏 `summer`・秋 `autumn`・冬 `winter` は別の無料設定で、取得品数には含めない。それぞれ「いつもの けしき」へ戻せる。実時計、曜日、季節、連続日数、抽選、期間限定によって選択を閉じない。時計変更・reload・offlineで選択を回したり権利を失ったりしない。

既存の無料衣装 `original / scarf / cap`、音 `off / breeze / brook / evening`、旗の印 `leaf / star / flower / wave` は同じ意味で残す。追加品を持っていなくても、従来の名前・衣装・音・旗・全景を使える。

## 3. 資格・試用・取得・装備を分ける

資格の正本は、現在のprofileに保存済みの `growth.discoveries` と `workshop.creations`。蝶と葉鳥は該当discovery ID、音は `partId === 'bell'` の検証済みcreation記録を照合する。旧版で保存した観察も資格になり、もう一度の遭遇、学習、制作を強制しない。

来訪候補、未保存の演技通知、図鑑を開く操作、bell部品の所有・組立・配置、未完了の水路、音を聞くボタンだけでは資格にならない。bellは仕様37の実可視到達後の保存を使い、音offで実演を見届けた記録も同じ資格とする。観察記録を新しい資格tableへ複製せず、取得時に正本を読む。取得後の所有は専用の所有配列に残り、装備を外しても資格と所有は消えない。

未所持・資格未達でも無料で試せる。住民の試着は本人が選んだ登場済み住民を同じ実rigの近景で示す。全景、足跡の歩行、音、旗、アルバム外装も取得後と同じ実装で試す。模様・足跡を試すために既存の家具や展示を移動しない。試用で新しい観察や共有記憶、学習実績を保存しない。

画面は「無料の設定」「ほしで取得」「観察済みなら0ほしで取得」「所持済み」を区別する。価格、残高、不足数、未達条件を示し、資格だけで自動取得・自動装備しない。「25ほしで もらう」「みつけた しるしを もらう」等の明示取得を保存してから、別の「このこに つける」「この おとに する」で装備する。取得の保存完了だけで現在の景色や音を切り替えない。

一度に試すのは選択した一つの商品または一つの無料設定で、保存済み状態との差を見せる。衣装・模様・足跡などを順次確定して組み合わせられる。41では複数の未確定商品をまとめて買う操作を設けない。取消・閉じる・学習開始・profile変更・背景化は未確定の試用を破棄する。未知結果の保存意図まで取消して未保存と決めつけない。

## 4. 保存モデルと具体的なAPI案

`IslandRecord.schemaVersion: 1` とDB v8を保ち、optionalな `IslandRecord.expression?: IslandExpressionState` を追加する。表記上の型別名は上表のstable IDに一致させる。

```ts
type IslandExpressionOutfitId = 'raincoat' | 'star-beret';
type IslandExpressionPatternId = 'river-check' | 'butterfly-stitch';
type IslandExpressionTrailId = 'leaf-trail' | 'water-ring-trail';
type IslandExpressionSoundId = 'shell-three-notes';
type IslandExpressionCoverId = 'leaf-album-cover';
type IslandExpressionStampId = 'butterfly-stamp';
type IslandExpressionFlagTrimId = 'leaf-bird-flag-trim';
type IslandExpressionItemId = IslandExpressionOutfitId
  | IslandExpressionPatternId | IslandExpressionTrailId
  | IslandExpressionSoundId | IslandExpressionCoverId
  | IslandExpressionStampId | IslandExpressionFlagTrimId;
type IslandDayPeriod = 'morning' | 'day' | 'evening';
type IslandSeason = 'spring' | 'summer' | 'autumn' | 'winter';

interface IslandExpressionSelection {
  version: 1;
  residents: Record<IslandResidentId, {
    outfit: IslandExpressionOutfitId | null;
    pattern: IslandExpressionPatternId | null;
    trail: IslandExpressionTrailId | null;
  }>;
  soundscape: IslandExpressionSoundId | null;
  environment: { period: IslandDayPeriod | null; season: IslandSeason | null };
  album: { cover: IslandExpressionCoverId | null; stamp: IslandExpressionStampId | null };
  flagTrim: IslandExpressionFlagTrimId | null;
}

interface IslandExpressionState {
  version: 1;
  ownedItemIds: IslandExpressionItemId[];
  selection: IslandExpressionSelection;
}
```

`expression`省略は「所有なし、全selectionはnull」を読み取り時だけ解決する。衣装nullは既存 `experience.residents[id].look`、収集音nullは既存 `experience.ambience` を使う。他のnullは追加なしで、朝夕・季節nullは現在の外見styleの従来描画をそのまま使う。古い夜空テーマを起動時に昼へ変えない。defaultの読み取り、通常の学習writer、観察資格の成立でこの拡張を勝手に永続化しない。

存在するstateは全キーと全3住民を必須にし、余分なキー、未知version/ID、誤ったslotのID、重複所有、10件超、穴あき配列を拒否する。所有配列はカタログ順のcanonical値で保存する。装備した非nullのIDはすべて同profileの所有に含まれることを検査する。clone・比較関数も全selectionを扱い、不正な保存を既定値へ直して上書きしない。朝夕/季節に所有検査や残高減算を付けない。

専用操作は次の判別unionとし、callerの任意state・価格・資格boolean・所有配列・snapshotを受け取らない。

```ts
type IslandExpressionEquipAction =
  | { type: 'equip-outfit'; residentId: IslandResidentId; itemId: IslandExpressionOutfitId | null }
  | { type: 'equip-pattern'; residentId: IslandResidentId; itemId: IslandExpressionPatternId | null }
  | { type: 'equip-trail'; residentId: IslandResidentId; itemId: IslandExpressionTrailId | null }
  | { type: 'equip-soundscape'; itemId: IslandExpressionSoundId | null }
  | { type: 'equip-album-cover'; itemId: IslandExpressionCoverId | null }
  | { type: 'equip-album-stamp'; itemId: IslandExpressionStampId | null }
  | { type: 'equip-flag-trim'; itemId: IslandExpressionFlagTrimId | null }
  | { type: 'period'; period: IslandDayPeriod | null }
  | { type: 'season'; season: IslandSeason | null };
type IslandExpressionAction = IslandExpressionEquipAction
  | { type: 'acquire'; itemId: IslandExpressionItemId };
interface IslandExpressionPreview {
  action: IslandExpressionEquipAction;
  selection: IslandExpressionSelection;
}

declare function getIslandExpression(island: IslandRecord): IslandExpressionState;
declare function hasValidIslandExpression(island: IslandRecord): boolean;
declare function canonicalIslandExpressionAction(value: unknown): IslandExpressionAction;
declare function getIslandExpressionEligibility(island: IslandRecord, itemId: IslandExpressionItemId):
  { eligible: boolean; reason?: 'ribbon-butterfly' | 'bell' | 'leaf-bird' };
declare function reduceIslandExpression(island: IslandRecord, action: IslandExpressionAction): IslandRecord;
declare function previewIslandExpression(island: IslandRecord, action: IslandExpressionEquipAction): IslandExpressionPreview;
// databaseの省略時は既存のdbを使用する。
declare function saveIslandExpression(profileId: string, expectedRevision: number,
  action: IslandExpressionAction, database?: typeof db): Promise<IslandRecord>;
```

`IslandExpressionPreview` は描画用の仮selectionと対象actionを返す別型とし、未所持品を装備した仮 `IslandRecord` を保存可能な正本として返さない。previewと装備は同じ純粋な選択変更関数・描画resolverを使い、preview入口だけで所有制約を免除する。未知IDやslot不一致はpreviewでも拒否する。保存writerへpreview objectを渡すAPIを設けない。

## 5. 既存の無料衣装・音との互換操作

現 `experience.residents[id]` はstrictな `{ name, look }` で、既存 `resident` actionはそのobject全体を置換している。追加模様などをこのobjectへ足さず、既存のenumも有料品を含む型へ曖昧に広げない。

既存experience writerへ `resident-name { residentId, name }` と `resident-look { residentId, look }` の細いactionを追加する。名前欄はname-only、無料衣装のボタンはlook-onlyへ接続する。既存のcombined `resident { residentId, name, look }` は互換として受理し、その明示lookを選択として扱う。過去receiptのactionを新しい形へ書き換えない。

| 明示操作 | 同じ純粋reducer・transactionで起こすこと |
|---|---|
| 追加衣装を装備 | 対象のexpression.outfitだけを設定。既存lookは外した時の戻り先として保持 |
| 無料lookを選択 | 対象のexperience.lookを設定し、expression.outfitをnullにする。元lookと同じ値でも省略しない |
| 名前だけ変更 | nameだけ変更し、look・追加衣装・模様・足跡を保持 |
| 旧combined resident操作 | name/lookをその意図通り更新し、対象の追加outfitをnullにする。模様と足跡は保持 |
| 追加衣装を外す | outfitをnullにし、保存されている無料lookを実際に表示 |
| 収集音を装備 | soundscapeを設定。無料ambienceは戻り先として保持し、音源の実効選択は収集音になる |
| 既存ambienceを選択 | ambienceを設定し、soundscapeをnullにする。offや以前と同じ値の選び直しでも必ず反映 |
| 収集音を外す | soundscapeをnullにして無料ambienceへ戻す |
| 既存の旗印を選択 | emblemを変更し、独立した旗飾りは保持。旗飾りは専用の外す操作でnullにする |

expressionが省略されていて消す対象がない場合、無料設定の保存だけでexpressionをmaterializeしない。追加衣装の解除や収集音の解除を、画面側の後続callbackや別writerに分けない。保存失敗で半分だけ変わる設計にしない。

表示上の選択状態は実効look/音を使う。追加衣装中に戻り先の無料capを「いま着ている」と表示せず、追加音中に戻り先のoffを「現在無音」と表示しない。profile全体の `soundEnabled === false` はすべての島音を止めるが、取得・装備選択を消さない。既存音offの明示選択は上表の通り追加音も解除する。

## 6. transaction・再送・画面退出

専用writerは既存 `islandTables`、所有profile検査、PWAの保存hold、共通writer lockを使う。別通貨、別所有table、学習profileへの配列は作らない。保存済み学習区間からのほし加算は既存契約のままにし、この機能から加算しない。

`['island-expression-v1', profileId, expectedRevision]` をreceipt IDとし、canonical actionを持つ `expression_changed` eventを既存islandEventsへ保存する。active profileと正本の検証後、**既存receiptとの完全一致をCAS・価格・資格判定より先に確認**する。同じreceiptなら現在の島を返し、取得・減算・装備・captureを再実行しない。異なるactionを同receiptで受け取ったら競合とする。

未処理の場合だけrevisionを照合し、acquireなら最新の資格・所有・残高を確認する。所有追加・必要数の減算・島revision/updatedAt・receiptは単一transactionで保存し、selectionは変えない。所持済みへの新規取得は `already-owned` として減算・新receiptを行わず装備へ案内する。equipは必要な所有だけを確認し、無料設定は残高を使わず保存する。既存財布の旧省略値の扱いも再利用し、互換残高を重ねて付与しない。

domainの失敗は少なくとも `invalid-state / unknown-action / not-owned / not-eligible / insufficient-stars / already-owned` を区別し、所有profile・known CASの失敗は既存repositoryの型を保持する。未分類のI/Oをknown CASと決めつけない。

native abortでは全tableが操作前と一致する。commit成功後の応答欠落は結果不明と表示し、元revision・canonical actionを保持する。別actionでpendingを上書きせず、明示retryで同じ意図を再送する。known CASだけは最新状態を読み、古い意図を自動で新revisionへ付け替えず本人が再選択する。

既存experienceのreceipt先照合も保持する。例として、無料capの保存成功後に合羽を装備した島へ古いcap保存の通知欠落retryが来ても、元receiptを返すだけで合羽を再び外さない。取得の古いretryから、その後に変えた装備を再適用することもない。

hookはprofile所有とactive/hidden/退出の世代を確認し、学習予約の保存待ちに入る時点で試用・音・新規writer開始を止める。開始済みtransactionはatomicに完了させるが、遅い成功から退出後の試着・演奏・別画面への遷移を始めない。保存結果の新しいisland/revisionは同profileの正本として即採用し、liveQueryの先着/後着や古いclosureで退行させない。元pendingのretry成功にも同じ規則を適用する。

## 7. 全景保存・旧snapshot・写真

既存3枠のsave/apply-layoutを使う。新しい保存は `IslandSavedSceneStyle` をv1/v2の判別unionへ拡張し、v2を生成する。

```ts
interface IslandSavedSceneStyleV2 {
  version: 2;
  residentLooks: Record<IslandResidentId, IslandResidentLook>;
  ambience: IslandAmbience;
  emblem: IslandEmblem;
  expression: IslandExpressionSelection;
}
```

保存するのは当時の確定済みの無料設定とexpression selection。所有、資格、残高、名前、写真棚、観察・作品・共有記憶、学習と成長をsnapshotに複製して巻き戻さない。アルバム外装は表示設定として含めるが、写真行や写真の並びを含めない。39の解決済み12部位・飾り・poseも同じ保存に残す。未確定のF03 mixやF05 previewをcaptureしない。

save-layoutのcallerは引き続きlayoutIdとnameだけを渡し、transaction内の現在の島からcaptureする。同receiptのretryは保存済みreceiptを先に見て返す。後の装備変更や別tab更新を、元の保存案へ再captureしない。保存したsceneStyleはdeep cloneし、rendererやpreviewから変更しない。

v2の試用と適用は同じ純粋reducerで、記録した全selectionをnullも含めて復元する。非nullの品が現在の所有にあること、全現在家具・後発取得・展示との衝突を確認し、失敗は全体拒否する。snapshot内の装備を使って未所持品の所有を増やさない。後から育った物や購入家具を消さず、現在の名前と所有を保ったまま再編集できる。

| 保存形式・用途 | 省略時と復元の規則 |
|---|---|
| sceneStyle自体がない旧配置案を現在へ適用 | 39の通り、現在の無料設定とF05選択を保持。古いcosmeticsの従来版描画の規則とは分ける |
| sceneStyle v1がある旧配置案を現在へ適用 | 記録済み無料look/ambience/emblemを復元する。無料look/音を有効にするため追加outfit/soundscapeを解除。v1にない独立した模様・足跡・朝夕・季節・外装は現在を保持 |
| sceneStyle v2の配置案を適用 | 記録した無料設定と全expression selectionを復元。所有・残高・資格は現在のまま |
| sceneStyleのない旧成長memoryを閲覧 | 従来の履歴rendererを維持し、現在のF05設定を注入しない。現在の島へ適用する操作とは別扱い |
| 新しい成長memoryを閲覧 | 有限の節目captureへoptionalなsceneStyle v2を追加し、当時の確定選択だけで描画する。現在の外見で補完しない |
| 保存済み写真を閲覧/出力 | 当時の画像bytesとメタデータを保持。現在の外装を写真画像へ焼き込まない |

v1の配置案は当時記録しなかったF05要素まで完全復元した証拠にはしない。新しい成長snapshotの追加で、島本体のexpression省略を初期化したり、通常の回答保存へ画像処理を入れたりしない。既存の初期/成長/拡張memoryの件数と学習上の意味は変えない。

写真の本体・thumbnail・sha256・寸法・撮影時刻・当時の島名/対象名は変更しない。葉表紙と蝶stampは写真カード外側の余白に描き、原画ダウンロードは元PNGのまま。装飾済み合成画像の別出力は今回追加しない。新しいカメラで撮った写真には、その撮影時の実rendererの衣装・旗・季節等が写る。未確定previewから確定済みの姿として写真保存する導線は設けない。

## 8. 実景・身体・音の受入契約

世界、近景、試用、装備、全景比較、写真は一つのrendererと同じモデルを使う。カタログ絵だけで実装を代替せず、無料/追加品の差をphone/tabletで示す。selectionの変更で同一住民のgroup、名前、身体のrig、成長、家具、展示、歩行経路の正本を置換しない。

追加衣装は独立した所有groupで切り替え、originalへ戻した時は追加衣装groupを確実に消す。既存rabbit/foxの身体に含まれる固定の衣装は従来通り保持する。帽子は目・耳・視線を隠さず、合羽は手と足を動かせる形にする。模様はbodyの可視な布片を使い、original/scarf/cap/raincoat/star-beretの全組合せで見える。服で覆う場合は同じ模様の布片を外側へ移し、消えた選択を保存成功扱いにしない。

歩行、座る、物を運ぶ、工作と住民の共同利用、望遠鏡・ハンモック・茶卓の接点で3住民を検証する。衣装を理由に接点をずらしたり、保存上の占有半径を超えたりしない。現在/試用の比較は同じ倍率で、帽子・耳を含む最大姿勢のboundsを収める。

足跡は実際の歩行中の足の接地から出し、frame数・架空の経路・停止中のtimerから生成しない。上限は1住民8片、全島24片、各片の寿命1.2秒以内とする初期制作契約。固定poolを再利用し、上限到達では古い片を再利用する。足を浮かせて運ばれる、座る、眠る時は発生させない。水輪は接地の視覚表現で、水の物理・床・衝突判定を変えない。

着座中に試歩を選んだ場合も同じ住民を借り、実際の支持面から離席して足が地面に着いてから歩く。座面・背板・肘掛けと身体の接触を保ち、初点を座面内の地面へ移す操作や家具の一括除外で貫通を隠さない。尾は通常の着座姿勢でも背板を跨がないように畳み、離席では同じ関節を動かす。離席中は接地印を出さず、取消は元の位置・身体各部の姿勢へ戻す。実座面ray、足裏座標、離席から接地の連続した実画面を検証し、診断のphase名だけを証拠にしない。

静止で新規発生を止め、残った片は寿命内で消す。学習開始、背景化、退出、profile変更で全片を即座に隠して解放する。reduced motionでは拡大波紋と移動補間を抑え、1住民2片以下の短い接地印で同じ意味を伝える。毎frameにmesh/material/textureを生成しない。preview歩行もこの上限を共有する。

朝夕は環境の光と空の表情、季節は木・草・地面の少量の色や素材の表情へ作用する。解決済み12slotの形・配色の識別、成長段階、F04接点、水の浮沈/透過・歩行可能領域を保つ。冬でも地形を氷の床に変えず、季節選択を自然観察の資格や出現抽選に使わない。組合せごとの見え方を同じ純粋resolverで決め、実時計や未保存乱数を読むfallbackを作らない。

収集音は既存の単一の島環境音エンジンを拡張する。`shell-three-notes` が未知enumの分岐でevening音へ落ちないよう、実際に区別できる三音の音源を持つ。短い試聴は明示gestureから一回の三音句を鳴らし、装備時の音景も同じ音色を使う。音景中の句は重ねず、間隔12秒以上、同時発音3声以内、1句2秒以内を初期制作上限とする。細かな音量・間隔の良さは実聴で別判定する。

初回WebAudioの起動はtrusted pointer/key gestureへ結び、blocked時に表示だけplayingへ進めない。音off、学習開始、hidden、退出、profile変更でtimer・voice・nodeと遅いstartの世代を止める。背景復帰時に過去の試聴を再生しない。装備済み音景の再開は現在profile・active・soundEnabledとgesture解放状態を確認する。学習の声や問題音のcontextを工作/環境音側から止めない。無音でも観察資格、商品、装備中/解除の状態が分かる。

旗飾りは既存の印と島名を隠さず、既存の家まわりの表示領域で納める。『はたの かざり』を選ぶと、同じ実旗・旗印・鳥飾り・島名札が入る近景へ切り替え、『しま全体を みる／はたを みる』で往復できる。現在・未所持試用・試用取消・装備・取り外しで画角と倍率は固定し、装備の有無で自動拡大しない。既定の無料の旗印と島名札が通常非表示の旧履歴では、この近景中だけ同じ実模型を表示し、近景解除で元の可視状態へ戻す。別商品・画面退出・学習開始で焦点を解除し、帽子等の住民近景へ持ち越さない。これは保存も報酬取得も発見も伴わない閲覧操作であり、実画面でphoneの鳥の輪郭と旗印、島名札を確認するまで視覚合格にしない。

鳥飾りは同じGroup・形状を使い、屋根の外に出る旗の自由端の上寄りへ短い紐で付ける。紐の上端は実際の旗布の自由端へ、下端は鳥の葉の胴へ接続し、旧/newの星の家のドームや成熟時の小屋根へ埋めない。旗布・旗印・島名札の位置や外見、家と歩行領域をこの修正で動かさない。旗近景の無料試用表示は同じ文言・文字サイズを右上の小幅に納め、左側の実旗を覆わない。全景や他商品の試用表示は従来の幅を維持する。

アルバム外装は写真の焦点と操作面を覆わない。音・旗・模様・足跡に付随する資源は所有元で破棄し、何度試用・退出しても増え続けない。

## 9. 依存方向と実装責任の案

現sourceでは `workshop.ts → experience.ts` が名前正規化のruntime importであり、`growth.ts → catalog` と `experience.ts → catalog` もある。expressionからworkshop/growthのvalidatorを呼び戻し、経験設定からexpressionへ依存すると循環を作りやすい。資格は全島の正当性をrepository境界で検証した後、正本の該当配列を純粋に読む。expression内部から `assertIsland` を再帰呼出ししない。

| 責任候補 | 境界 |
|---|---|
| 新 `residentIdentity.ts` | 既存の住民ID/無料look/音/旗の定数と型だけを依存のない末端へ移す。experienceからの既存exportは再exportで維持し、二重の定数表を作らない |
| 新 `expression.ts` | 有限カタログ、state/selection、strict検証、clone、資格の純粋読取、canonical、取得/装備/preview。identityと既存財布を利用し、experience/workshop/growth/repositoryをruntime importしない |
| 新 `sceneStyle.ts` | v1/v2型・検証・clone・capture。identityとexpressionの下位関数を使い、experience/growthはtype-only参照か狭い入力形だけで受ける |
| experienceとgrowth | sceneStyleの共通関数を呼ぶ側。experienceは無料設定の解除規則と全景apply、growthは有限節目の読み取りcaptureを担当 |
| 新 `expressionRepository.ts` / 既存repository・types | 所有profile、receipt先照合、CAS、atomic保存、event/typeの狭い追加。DB store/indexは増やさない |
| 専用hook・既存experience UI・Page | exact pending、free name/look操作、実効選択表示、previewと確定の分離、同じ学習へ戻る取消 |
| 既存renderer・音engine・写真/全景表示 | 単一rig/scene、選択resolver、有限pool、資源解放、旧snapshotと写真の表示契約 |

型のimportだけで済む依存は `import type` にする。上記は責任分割の案であり、実装担当を自動的に割り当てるものではない。検証、比較、clone、receiptのいずれかだけが旧型のまま残る部分導入をしない。未知fieldを理解しない旧buildへのdowngradeやfield削除を回復策にしない。

